# a wrong guess here means a smaller/rougher order, never an oversized one.
DEFAULT_QTY_STEP  = {"ETH": 0.01, "QQQ": 0.01}
DEFAULT_PRICE_STEP = {"ETH": 0.01, "QQQ": 0.01}

