def _startup_progress():
    """Live readiness snapshot for every subsystem curses_main starts on its
    own background thread — used only by the loading screen to decide when
    to stop showing the splash and cut over to the real dashboard loop.
    Reuses each subsystem's OWN existing status signal (GEX_STATUS/
    STATUS_ENGINE_STATE/APP_STATE.instruments) rather than a parallel
    tracking mechanism, plus the two dedicated one-shot Events
    (_backfill_ready/_ch_ready) added for the two subsystems that had no
    such "first cycle done" signal of their own. Returns a list of
    (label, done) pairs, engine first then per-asset groups in the same
    order curses_main itself starts their threads in.

    Client Mode starts none of those threads at all (see curses_main's own
    CLIENT_MODE-gated thread-startup block) — its only background thread is
    _sync_client_connect_loop, so its own readiness checklist is just
    "connected to the Server" then "received a first pushed snapshot",
    against SYNC_CLIENT_STATUS/SYNC_CLIENT_LAST_MSG_TS instead."""
    if CLIENT_MODE:
        return [("Connecting to server", SYNC_CLIENT_STATUS[0] == "connected"),
                ("Received first snapshot", SYNC_CLIENT_LAST_MSG_TS[0] > 0.0)]
    # 2026-08-12 user request: one consolidated line per subsystem (both
    # assets' own readiness ANDed together) instead of a separate ETH/QQQ
    # line each — the per-asset granularity was never actually load-bearing
    # here (this whole function only ever feeds a splash screen, not a
    # real diagnostic), and by the time Net Drift/Volatility Drift's own
    # lines were added tonight, 13 individual rows was pushing the loading
    # screen's own bust-art/wordmark fallback logic (draw_loading_screen)
    # into unnecessarily dropping the sword-and-shield art on a normal
    # ~60-row terminal. 8 consolidated rows comfortably fits the full
    # bust+wordmark combo again.
    steps = [("Trading engine", bool(APP_STATE.snapshot()["instruments"]))]
    steps.append(("Order-flow backfills", all(_backfill_ready[a].is_set() for a in ASSETS)))
    steps.append(("GEX engines", all(GEX_STATUS.get(a) not in (None, "connecting…") for a in ASSETS)))
    steps.append(("Status engine", STATUS_ENGINE_STATE[0] != "connecting…"))
    steps.append(("VWAP/VP engines", all(_ch_ready[a].is_set() for a in ASSETS)))
    steps.append(("Net Drift engines", all(DRIFT_READY[a].is_set() for a in DRIFT_ASSETS)))
    steps.append(("CVD engines", all(CVD_READY[a].is_set() for a in CVD_ASSETS)))
    steps.append(("Volatility Drift engines", all(VOLDRIFT_READY[a].is_set() for a in VOLDRIFT_ASSETS)))
    steps.append(("Macro Options Flow engine", OPTFLOW_READY.is_set()))
    if not DRY_RUN:
        # Only shown at all on a live launch — a DRY_RUN/paper session never
        # starts _phemex_preflight_thread (see curses_main's own thread-
        # startup block), so there'd be nothing real for this line to mean.
        steps.append(("Phemex trade-execution test", _phemex_preflight_done.is_set()))
    return steps

LOADING_GAP = 2   # blank rows between each of the loading screen's own
                    # sections (art / wordmark / tagline / checklist) when
                    # there's room — draw_loading_screen tightens this down
                    # (2 -> 1 -> 0) before ever dropping the bust art on a
                    # merely-short-on-a-few-rows terminal (the 40-row bust
                    # art is tall enough that "just drop it" was throwing
                    # away the splash entirely on perfectly reasonable
                    # ~60-row terminals over a couple of rows of padding).

def _loading_content_h(show_bust, show_word, bust_h, word_h, total_n, gap):
    """Total row count draw_loading_screen's own layout below actually
    uses for a given show_bust/show_word/gap combination — shared by both
    the real draw call and its own size-gating checks so they can't
    disagree. The tagline-to-checklist gap is deliberately one row
    tighter than the other two (see its own `max(0, gap - 1)` in
    draw_loading_screen) — kept in sync here too."""
    h = 0
    if show_bust:
        h += bust_h + gap
    h += word_h if show_word else 1
    h += gap + 1 + max(0, gap - 1) + total_n
    return h

def _loading_best_gap(show_bust, show_word, bust_h, word_h, total_n, avail_rows):
    """Largest gap in (LOADING_GAP, 1, 0) whose resulting _loading_content_h
    fits avail_rows, or None if even a gap of 0 doesn't fit."""
    for gap in (LOADING_GAP, 1, 0):
        if _loading_content_h(show_bust, show_word, bust_h, word_h, total_n, gap) <= avail_rows:
            return gap
    return None

def draw_loading_screen(db, rows, cols, steps, tick):
    """Full-screen ASCII splash — the user-supplied sword-and-shield art
    plus a live per-subsystem checklist built from `steps` (see
    _startup_progress). Degrades gracefully on a small terminal: first
    tightens the inter-section gap, then drops the bust art, then the
    wordmark, rather than ever risking an off-screen curses write."""
    done_n = sum(1 for _, d in steps if d)
    total_n = len(steps)

    bust_w = max(len(l) for l in _ATHENA_BUST_ASCII)
    bust_h = len(_ATHENA_BUST_ASCII)
    word_w = max(len(l) for l in _ATHENA_WORDMARK_ASCII)
    word_h = len(_ATHENA_WORDMARK_ASCII)
    tagline = "AUTOMATED TRADING ALGORITHM"
    avail = rows - 1

    show_bust = show_word = False
    gap = 0
    if cols >= bust_w + 2:
        g = _loading_best_gap(True, True, bust_h, word_h, total_n, avail)
        if g is not None:
            show_bust = show_word = True
            gap = g
        else:
            # 2026-08-12 user-reported (sword-and-shield bust missing on a
            # 61-row terminal): bust+full-wordmark didn't fit even at
            # gap=0 — Net Drift's and Volatility Drift's checklist lines
            # (4 more rows total) pushed content_h exactly 1 row past
            # avail. The old fallback here dropped the ENTIRE 40-row bust
            # to save that single row — try bust + the compact
            # "A T H E N A" title line (word_h - 1 rows cheaper) BEFORE
            # giving up on the bust art entirely; the checklist/rendering
            # code below already handles show_bust=True/show_word=False
            # correctly (falls to the compact title), this was purely a
            # missing intermediate rung in the degradation ladder.
            g2 = _loading_best_gap(True, False, bust_h, word_h, total_n, avail)
            if g2 is not None:
                show_bust = True
                gap = g2
    if not show_bust and cols >= word_w + 2:
        g = _loading_best_gap(False, True, bust_h, word_h, total_n, avail)
        if g is not None:
            show_word = True
            gap = g

    content_h = _loading_content_h(show_bust, show_word, bust_h, word_h, total_n, gap)
    y = max(0, (avail - content_h) // 2)

    if show_bust:
        x = max(0, (cols - bust_w) // 2)
        for line in _ATHENA_BUST_ASCII:
            db.puts(y, x, line[:max(0, cols - x)], P_CYAN)
            y += 1
        y += gap

    if show_word:
        x = max(0, (cols - word_w) // 2)
        for line in _ATHENA_WORDMARK_ASCII:
            db.puts(y, x, line[:max(0, cols - x)], P_YELLOW, curses.A_BOLD)
            y += 1
    else:
        title = "A T H E N A"
        db.puts(y, max(0, (cols - len(title)) // 2), title[:cols], P_YELLOW, curses.A_BOLD)
        y += 1
    y += gap

    tag_x = max(0, (cols - len(tagline)) // 2)
    db.puts(y, tag_x, tagline[:cols], P_DIM)
    y += 1 + max(0, gap - 1)

    spin = LOADING_SPINNER[tick % len(LOADING_SPINNER)]
    label_w = max(len(s) for s, _ in steps)
    list_x = max(0, (cols - (label_w + 5)) // 2)
    for label, done in steps:
        mark = "[OK]" if done else f"[{spin} ]"
        pair = P_GREEN if done else P_DIM
        db.puts(y, list_x, mark, pair, curses.A_BOLD if done else 0)
        db.puts(y, list_x + 5, label[:max(0, cols - list_x - 5)], pair)
        y += 1

    hint = f" {done_n}/{total_n} ready — q=quit  any other key=skip "
    db.puts(rows - 1, 0, hint.ljust(cols)[:cols], P_STATUS)

# ── Main curses loop ───────────────────────────────────────────────────────────
def curses_main(stdscr):
    global PCT, NO_SESSION, ATHENA_ENABLED, SIZING_MODE, RISK_MODE, RISK_DOLLARS, TRADING_MODE
    global FEE_ETH_PCT, FEE_QQQ_PER_UNIT, CLIENT_MODE, SERVER_MODE
    curses.curs_set(0)
    stdscr.keypad(True)
    curses.mousemask(0)
    init_curses_colors()
    stdscr.timeout(100)

    # Login, then Server/Client mode pick — BEFORE anything trading/network-
    # related exists. This ordering is what makes Client Mode provably
    # inert on the trading side: every engine/backfill/GEX/status/CH thread
    # start below is gated on CLIENT_MODE, which isn't even set until this
    # returns, so there's no window where a Client briefly touches any of
    # that (see the sync-layer module docstring above CLIENT_MODE).
    if not _login_screen(stdscr):
        return
    while True:
        mode = _mode_select_screen(stdscr)
        if mode is None:
            return
        if mode == "server":
            SERVER_MODE, CLIENT_MODE = True, False
            _server_info_screen(stdscr)
            break
        else:
            candidates = _client_connect_screen(stdscr)
            if candidates is None:
                continue   # Esc/empty address — back to the mode picker, not a crash
            CLIENT_MODE, SERVER_MODE = True, False
            SYNC_SERVER_CANDIDATES[:] = candidates
            break
    stdscr.erase()

    if not CLIENT_MODE:
        threading.Thread(target=_run_engine, daemon=True).start()
        if not DRY_RUN:
            threading.Thread(target=_phemex_preflight_thread, daemon=True).start()
        else:
            _phemex_preflight_done.set()   # nothing to test — don't make the
                                             # loading screen wait on a step
                                             # that will never run
        for asset in ASSETS:
            feed_starters = []
            # QQQ's live tape prefers Athena's own dedicated Alpaca account
            # (real QQQ shares, matching footprint.py's own closed-bar source
            # for QQQ) over Phemex's thinner QQQUSDT perp — per explicit user
            # request. Falls back to the Phemex tape if those credentials
            # aren't set, so a missing .env entry degrades gracefully instead
            # of leaving QQQ's live chart with no feed at all.
            if asset == "QQQ" and ALPACA_API_KEY_ID and ALPACA_API_SECRET_KEY:
                feed_starters.append((_alpaca_trade_ws, (asset, _quit_evt)))
                # 2026-08-26 user request: sim fills/PnL/funding must use
                # Phemex's own QQQUSDT price (the real account only ever
                # trades that, never real QQQ shares), even though Alpaca's
                # real-stock tape stays QQQ's own signal/confirmation feed
                # above — this thread runs SOLELY to keep PHEMEX_LAST_PRICE
                # current, feed_live_tape=False so it never touches the
                # blended LIVE_TAPE Alpaca already owns for QQQ.
                feed_starters.append((_phemex_trade_ws, (asset, _quit_evt, False)))
            else:
                if asset == "QQQ":
                    console_log(f"{YLW}ALPACA_API_ATHENA_ID/ALPACA_API_SECRET_KEY_ATHENA not set — "
                                f"QQQ live tape falling back to Phemex QQQUSDT{RST}")
                feed_starters.append((_phemex_trade_ws, (asset, _quit_evt)))
            # ETH's live tape aggregates Phemex + Kraken + Coinbase — matching
            # footprint.py's own multi-exchange source for ETH's closed bars
            # exactly, so a live bar isn't blind to a real print that happened
            # to land on Kraken/Coinbase first (see the module-level comment
            # above KRAKEN_WS_URL for the confirmed live discrepancy this fixes).
            if asset == "ETH":
                feed_starters.append((_kraken_trade_ws, (asset, _quit_evt)))
                feed_starters.append((_coinbase_trade_ws, (asset, _quit_evt)))
            # Backfill runs to completion on its OWN thread BEFORE this asset's
            # live feed(s) start — see _backfill_then_feeds's own docstring for
            # why (mirrors footprint.py's initialize_today()-then-start_feeds()
            # sequencing without blocking curses startup for both assets).
            threading.Thread(target=_backfill_then_feeds, args=(asset, feed_starters), daemon=True).start()
            # GEX engine (Phase 2 of the standalone-merge plan) — one
            # background thread per asset, independent of the footprint
            # backfill/feed sequencing above (GEX has its own separate data
            # source entirely — options chains, not trade prints — so there's
            # no shared race to avoid the way footprint's late-trade guard
            # requires backfill-before-live-feed).
            threading.Thread(target=_gex_engine_loop, args=(asset, _quit_evt), daemon=True).start()
        threading.Thread(target=_fast_publish_loop, args=(_quit_evt,), daemon=True).start()
        # Status engine (Phase 3 of the standalone-merge plan) — 3 threads,
        # same cadences/shape as status.py's own main()+live_price_loop+
        # snapshot_logger_loop (one full-refresh cycle covers BOTH assets at
        # once, unlike the GEX engine above which is genuinely per-asset).
        threading.Thread(target=_status_full_refresh_loop, args=(_quit_evt,), daemon=True).start()
        threading.Thread(target=_status_live_price_loop, args=(_quit_evt,), daemon=True).start()
        threading.Thread(target=_status_snapshot_loop, args=(_quit_evt,), daemon=True).start()
        # CH engine (Phase 3b of the standalone-merge plan) — charthacker.py's
        # own live-WS-fed VAH/VWAP layer, one thread per asset (mirrors its own
        # ws_phemex/ws_yahoo feeds) plus one shared export loop (mirrors its
        # status_export_loop). Independent of the status engine threads above —
        # evaluate_hpls picks this up automatically via read_status_charthacker_
        # export the moment it starts producing fresh data, no other change
        # needed (same "zero consumer-side changes" pattern as every prior phase).
        threading.Thread(target=_ch_engine_thread_eth, args=(_quit_evt,), daemon=True).start()
        threading.Thread(target=_ch_engine_thread_qqq, args=(_quit_evt,), daemon=True).start()
        threading.Thread(target=_ch_export_loop, args=(_quit_evt,), daemon=True).start()
        # Markets overview (2026-08-27) — used to be an on-demand thread
        # started only while the standalone Markets mode was active; now
        # that it's a toggle on the QQQ OHLC pane, it runs continuously
        # from startup like every other always-on engine here, so the
        # data is already populated the first time a user toggles to it.
        threading.Thread(target=_markets_refresh_loop, args=(_quit_evt,), daemon=True).start()
        # Phemex bid/ask (2026-08-27 user request) — dashboard's own
        # real-time bid/ask/spread readout next to each asset's price.
        threading.Thread(target=_phemex_bid_ask_poller, args=(_quit_evt,), daemon=True).start()
        # Net Drift engine — ported from drift.py, one always-on thread per
        # asset (both ETH and QQQ tracked continuously regardless of which
        # [M] mode is currently displayed, same as GEX/Status/CH above) —
        # see _drift_engine_loop's own docstring for why this is two simple
        # per-asset threads rather than a port of drift.py's own Controller/
        # BackgroundTracker split.
        for _drift_asset in DRIFT_ASSETS:
            threading.Thread(target=_drift_engine_loop, args=(_drift_asset, _quit_evt), daemon=True).start()
        # CVD — ported from cvd.py (2026-08-16). No dedicated feed thread of
        # its own: it's a passive second consumer of the ALREADY-always-on
        # footprint feed threads above (Phemex/Kraken/Coinbase/Alpaca, all
        # already calling LiveTape.ingest(), which now also calls
        # _cvd_ingest_trade() — see that hook's own comment). Backfills from
        # each asset's own session start (00:00 CT for QQQ, 19:00 CT for
        # ETH) on whatever bar interval was last used today (2026-08-17
        # user request), race-safe against the ALREADY-running live feeds
        # via _cvd_ingest_trade's own buffering — see
        # _cvd_backfill_then_ready's own docstring. Only sets CVD_READY once
        # that backfill has actually landed.
        for _cvd_asset in CVD_ASSETS:
            threading.Thread(target=_cvd_backfill_then_ready, args=(_cvd_asset,), daemon=True).start()
        # Volatility Drift engine — ported from vol-drift.py, same always-on
        # per-asset-thread shape as Net Drift's own above.
        for _voldrift_asset in VOLDRIFT_ASSETS:
            threading.Thread(target=_voldrift_engine_loop, args=(_voldrift_asset, _quit_evt), daemon=True).start()
        # Macro Options Flow engine — ported from opt_dashboard.py, made
        # always-on per explicit user request (2026-08-15) — unlike
        # Markets/Chain either side of it in the [M] cycle, which stay
        # on-demand (started/stopped on mode entry/exit instead).
        threading.Thread(target=_optflow_refresh_loop, args=(_quit_evt,), daemon=True).start()

    # Sync layer — the ONE thread Client Mode ever starts (never touches an
    # exchange, a broker credential, or the trading engine); Server Mode
    # starts one listener thread PER resolved address (LAN and/or VPN)
    # alongside its normal engine threads above.
    if CLIENT_MODE:
        threading.Thread(target=_sync_client_connect_loop,
                          args=(SYNC_SERVER_CANDIDATES, _quit_evt),
                          daemon=True).start()
    if SERVER_MODE:
        for label, getter in (("LAN", _get_lan_ip), ("VPN", _get_vpn_ip)):
            ip = getter()
            if ip:
                SYNC_SERVER_BIND_IPS.append((label, ip))
                threading.Thread(target=_sync_server_listen, args=(label, ip, _quit_evt), daemon=True).start()
        if SYNC_SERVER_BIND_IPS:
            threading.Thread(target=_sync_data_view_loop, args=(_quit_evt,), daemon=True).start()
        # else: already surfaced on _server_info_screen — Server just runs
        # with no listener, never falls back to binding 0.0.0.0.

    # Loading screen — holds here (all the above threads are already running
    # in the background) until every one of them reports its first cycle
    # done, or LOADING_MAX_WAIT_SEC elapses, or the user skips/quits.
    loading_deadline = time.time() + LOADING_MAX_WAIT_SEC
    loading_tick = 0
    while not _quit_evt.is_set():
        steps = _startup_progress()
        if all(done for _, done in steps) or time.time() > loading_deadline:
            break
        lrows, lcols = stdscr.getmaxyx()
        ldb = DoubleBuffer(lrows, lcols)
        draw_loading_screen(ldb, lrows, lcols, steps, loading_tick)
        ldb.flush(stdscr)
        loading_tick += 1
        key = stdscr.getch()
        if key != -1:
            if key in (ord("q"), ord("Q")):
                _quit_evt.set()
            break
    curses.napms(30)   # one extra idle wait so the tail of the splash's own
                        # last frame doesn't visibly tear against the
                        # dashboard's first full repaint below
    stdscr.clearok(True)   # force a full repaint for the dashboard's first
                            # frame — the splash left the real screen content
                            # in an unrelated state, so DoubleBuffer's own
                            # cell-diff can't be trusted for just this one frame

    rows, cols = stdscr.getmaxyx()
    db = DoubleBuffer(rows, cols)

    # Chart scroll/focus is purely a UI concern (which historical window
    # each pane shows) — lives only on this thread, never touches AppState
    # or the trading engine. hscroll_bars follows footprint.py's own "N
    # bars back from the newest" convention; 0 is always the live tail.
    chart_scroll = {"ETH": 0, "QQQ": 0}
    # Vertical price-axis pan for the footprint dashboard's own OHLC view —
    # a shift-the-window-before-p2r offset, scoped per-asset like
    # chart_scroll itself.
    ohlc_vert_offset = {"ETH": 0, "QQQ": 0}
    ohlc_show_sessions = True   # shared (not per-asset) view prefs, same as
    ohlc_line_mode = False       # profile_mode/chart_zoom already are
    ohlc_vp_historical = True    # [4] — VAH/VAL/POC "Historical Mode"
                                   # (stepped developing trace) vs today's
                                   # only "Normal Mode" (flat current-value
                                   # line). 2026-08-27 user request: on by
                                   # default.
    ohlc_show_markets_qqq = False   # [Y] — QQQ pane ONLY: swap the candle
                                   # chart for the Markets overview (2026-08-27,
                                   # folded in once the standalone Markets mode
                                   # was removed). QQQ-only (not a per-asset
                                   # {"ETH":.., "QQQ":..} dict like the state
                                   # above) since Markets isn't QQQ data at all —
                                   # it's a broader 8-asset macro overview, just
                                   # surfaced here since the QQQ pane goes
                                   # stale/less useful whenever QQQ's own market
                                   # is closed.
    # [H] full-key-menu overlay state for every mode — 2026-08-26 user
    # request: every mode's dense one-line footer was hard to read and
    # didn't fit on screen. See _draw_key_menu_overlay's own docstring for
    # the shared rendering.
    mode_help_open = {"trading": False, "gex": False, "drift": False, "cvd": False,
                       "voldrift": False, "chain": False,
                       "macro_options": False, "status": False}
    mode_help_scroll = {k: 0 for k in mode_help_open}
    chart_focus = "ETH"
    chart_zoom = False   # [Z] — fullscreen whichever pane is [Tab]-focused
                          # instead of the normal ETH/QQQ side-by-side split
    # [X] crosshair — re-created 2026-07-25 per explicit user request
    # (footprint.py's own [Z]/[X] crosshair was deliberately dropped
    # during the original port as "always a live tail, read-only").
    # footprint.py's own Z/X keys aren't both available here — [Z] is
    # already Athena's own pane-zoom toggle — so this uses ONE key,
    # [X], to activate/deactivate, and repurposes the EXISTING [←]/[→]
    # keys to move the crosshair bar-by-bar (instead of panning the
    # whole view) while it's active, auto-panning the view to follow it
    # via _footprint_crosshair_clamp exactly like footprint.py's own
    # auto-follow does. Esc/[Home] deactivate it, same as every other
    # panning key already resets to live.
    chart_crosshair_active = {"ETH": False, "QQQ": False}
    chart_crosshair_idx = {"ETH": 0, "QQQ": 0}      # "N bars back from newest"
    gex_mode = False   # full-screen GEX mode (Phase 2 of the standalone-
                        # merge plan), replacing the dashboard+chart
                        # entirely while active, same as data_view. Phase 4:
                        # [M] cycles Trading -> GEX -> Status -> Trading —
                        # gex_mode/status_mode are never both True at once;
                        # see the [M]/Esc key dispatch for each mode below.
    gex_by_strike = False   # [G] within gex_mode — dot-map (False) vs
                             # GEX-by-strike bar chart (True)
    gex_by_strike_net = False   # [N] within gex_mode's by-strike view
    gex_live_follow = {"ETH": True, "QQQ": True}      # time-axis auto-follow (dot-map)
    gex_view_end_idx = {"ETH": 0, "QQQ": 0}           # frozen time-axis index when panned
    gex_vert_follow = {"ETH": True, "QQQ": True}      # strike-axis auto-center
    gex_vert_center_idx = {"ETH": 0, "QQQ": 0}        # frozen strike-axis index when scrolled
    status_mode = False   # full-screen Status mode (Phase 3c) — the [M]
                            # cycle's next stop after GEX; see gex_mode above
    status_scroll = 0
    drift_mode = False   # full-screen Net Drift (Premium) mode, ported from
                          # drift.py — current cycle: Trading -> GEX -> Net
                          # Drift -> CVD -> Volatility Drift -> Chain ->
                          # Macro Options Flow -> Status -> Trading (Markets
                          # is a [Y] toggle on the QQQ OHLC pane, not its
                          # own cycle stop); see voldrift_mode below and
                          # each mode's own [M] key-dispatch branch for
                          # where the cycle actually advances).
    drift_live = {"ETH": True, "QQQ": True}         # [H] per-asset live/historical
    drift_view_date = {"ETH": None, "QQQ": None}     # per-asset — which date [H] is browsing
    drift_view_offset = {"ETH": 0, "QQQ": 0}         # per-asset pan/scroll — deliberately
                          # per-asset (unlike drift.py's own single ctrl.view_offset, which
                          # resets on [S]-switch) so Tab-switching ETH<->QQQ preserves each
                          # asset's own scroll position, matching the SAME per-asset state
                          # preservation gex_mode's own gex_live_follow/gex_view_end_idx/etc.
                          # already established for Tab-switching in THIS file.
    drift_bar_interval = DRIFT_DEFAULT_BAR_INTERVAL   # [B] — shared across both assets,
                          # matches drift.py's own ctrl.bar_interval (not per-symbol there either)
    drift_filtered_mode = True      # [F] — shared display toggle, matches ctrl.filtered_mode;
                                      # defaults ON per user request (2026-08-11)
    drift_net_volume_mode = True    # [N] — shared display toggle, matches ctrl.net_volume_mode
                                      # (2026-08-12: the old [V] venue-breakdown toggle was
                                      # removed entirely per user request — the breakdown is
                                      # now always shown wherever it applies, see draw_drift)
    drift_crosshair_active = {"ETH": False, "QQQ": False}   # [X] — 2026-08-15 user request:
                                      # OHLC + Net Volume/Volume readout for the selected column,
                                      # same convention as the footprint charts' own [X] crosshair.
    drift_crosshair_idx = {"ETH": 0, "QQQ": 0}   # columns back from the right edge of the
                                      # CURRENT view (0 = rightmost) — see draw_drift/
                                      # _drift_crosshair_clamp for how panning at the edges works.
    cvd_mode = False   # full-screen CVD mode, ported from cvd.py (2026-08-16) — sits
                        # between Net Drift and Volatility Drift in the [M] cycle:
                        # Trading -> GEX -> Net Drift -> CVD -> Volatility
                        # Drift -> Chain -> Macro Options Flow -> Status ->
                        # Trading.
                        # Always-on for both assets (piggybacks on the ALREADY-always-on
                        # footprint feed threads via the _cvd_ingest_trade hook inside
                        # LiveTape.ingest() — no dedicated CVD feed thread of its own).
    cvd_crosshair_active = {"ETH": False, "QQQ": False}   # [X] — same convention as
                                      # drift_crosshair_active above, per explicit user request
                                      # ("same crosshair/scrolling functionality used in other modes").
    cvd_crosshair_idx = {"ETH": 0, "QQQ": 0}
    cvd_view_offset = {"ETH": 0, "QQQ": 0}   # [←→]/[]/{} — bars scrolled back from the
                                      # live edge, same "hscroll_bars" convention footprint's
                                      # own charts use (2026-08-17: CVD previously only ever
                                      # showed the last screen-width of bars with no way to
                                      # pan further back, even once backfilled from session start —
                                      # per explicit user request, this now lets the crosshair/
                                      # pan keys reach all the way back through the whole day).
    cvd_zoom_group = 1     # [+]/[-] — shared across both assets, matches cvd.py's own
                            # single (not per-symbol) zoom_group
    cvd_show_btd = False   # [T] Big Trade Detector overlay — shared across both assets
    cvd_color_scheme = "green_red"   # [C] — shared across both assets
    voldrift_mode = False   # full-screen Volatility Drift mode, ported from
                             # vol-drift.py (2026-08-12) — sits between CVD
                             # and Markets in the [M] cycle (see
                             # cvd_mode's own comment above for the full
                             # cycle order).
    voldrift_live = {"ETH": True, "QQQ": True}
    voldrift_view_date = {"ETH": None, "QQQ": None}
    voldrift_view_offset = {"ETH": 0, "QQQ": 0}   # per-asset, same Tab-switch-preserving
                             # reasoning as drift_view_offset above
    voldrift_bar_interval = VOLDRIFT_DEFAULT_BAR_INTERVAL   # [B] — shared across both assets,
                             # matches vol-drift.py's own ctrl.bar_interval
    macro_options_mode = False   # full-screen Macro Options Flow mode, ported from
                                  # opt_dashboard.py (2026-08-15) — sits between Chain and
                                  # Markets/Status in the [M] cycle (Markets is now a [Y]
                                  # toggle on the QQQ OHLC pane rather than its own stop —
                                  # see _draw_markets_panel). Mute state lives in the
                                  # module-level OPTFLOW_MUTED box (not a plain local here)
                                  # — the background _optflow_refresh_loop thread needs to
                                  # read it before playing an alert, so [U]'s key handler
                                  # flips OPTFLOW_MUTED[0] directly. [U] remaps
                                  # opt_dashboard.py's own [M] (mute), which collides with
                                  # Athena's global "next mode" key.
    chain_mode = False   # full-screen Chain mode, ported from chain.py (2026-08-15) —
                          # on-demand, sits between Volatility Drift and Macro Options
                          # Flow in the [M] cycle.
    chain_thread = [None]
    chain_stop_evt = [None]
    chain_simple_mode = False   # [Y] — Strike/Vol/OI/Mark-only columns (chain.py's own -s flag)
    dashboard_hidden = False   # [H] — gives the chart the ENTIRE terminal,
                               # same row budget footprint.py's own
                               # full-screen view uses, for when even the
                               # compacted DASHBOARD_H isn't enough room
    reset_armed = False
    data_view = False
    # A Client's own local DRY_RUN is meaningless — Client Mode never trades,
    # so there's no reason anyone would launch it with --dry-run, and it has
    # nothing to do with whether the SERVER it's mirroring is in sim or live
    # mode. Defaulting to "real" there (this line's ordinary DRY_RUN-based
    # logic) meant a Client's [D]ata view opened on the "real" tab — which
    # always shows an empty trading log by design (see _gather_data_view_
    # payload's own "real" field) — with no visible sign the sim data (what
    # a paper-trading Server's user actually wants to see) was one [S]witch
    # away. Client Mode defaults straight to "sim" instead; [S] still flips
    # to "real" same as always if that's what's actually wanted.
    data_source = "sim" if (CLIENT_MODE or DRY_RUN) else "real"
    data_cache = {"source": None, "ts": 0.0, "events": [], "stats": None}
    trades_cache = {"source": None, "ts": 0.0, "trades": []}
    table_scroll = 0
    table_hscroll = 0   # [←]/[→] in Data view — see _draw_trades_table's own docstring
    data_table_info = (0, 0, 0, 0)   # (visible_rows, total, scroll, hscroll) — set
                               # from draw_data_view's own return each frame, so the
                               # footer's scroll hint never drifts from the table's
                               # real layout, AND (2026-08-21) so table_scroll/
                               # table_hscroll themselves get written back to their
                               # clamped values every frame — see
                               # _draw_trades_table's own docstring for why this
                               # closes the "scrolling freezes at the boundary" bug.
    activity_log_open = False   # [L] — popup overlay over the FULL
                                 # EVENT_LOG_MAXLEN buffer, not just the
                                 # dashboard's own last-2-lines preview
    activity_log_scroll = 0

    while not _quit_evt.is_set():
        new_rows, new_cols = stdscr.getmaxyx()
        if (new_rows, new_cols) != (rows, cols):
            # windows-curses/PDCurses doesn't reliably resync the Windows
            # Console buffer via curses.resizeterm() alone — the working
            # pattern (per charthacker.py's own resize-bug history) is a
            # full endwin()+refresh() teardown/reinit, not the naive one.
            try:
                curses.endwin()
                stdscr.refresh()
            except curses.error:
                pass
            rows, cols = new_rows, new_cols
            db = DoubleBuffer(rows, cols)
            stdscr.clearok(True)

        snap = APP_STATE.snapshot()
        footer_row = rows - 1

        profile_mode = PROFILE_MODES[_profile_mode_idx[0]]
        both_panes = False

        if data_view and CLIENT_MODE:
            # Client Mode has no local trade logs to scan — reads whatever
            # the Server last pushed instead (see SYNC_DATA_VIEW/
            # _data_view_apply_wire/_sync_data_view_loop). [S]witch source
            # still works exactly as before; it just changes which half of
            # the already-synced payload is shown, no request round-trip.
            with SYNC_DATA_VIEW_LOCK:
                src = SYNC_DATA_VIEW.get(data_source, SYNC_DATA_VIEW["sim"])
            data_table_info = draw_data_view(db, rows, cols, data_source, src["events"],
                                              src["stats"], src["trades"], table_scroll, table_hscroll)
            _, _, table_scroll, table_hscroll = data_table_info
        elif data_view:
            now_mono = time.time()
            # 2026-07-31 CRITICAL fix, user-reported ("the Balance and
            # possibly the Cumulative PnL have [not] been calculated
            # correctly from the very beginning... if you continue
            # through each trade and compare the Net PnL with what the
            # new Balance should be, you will see it is all incorrect"):
            # scan_all_trade_events's own 'pnl' field is the RAW per-LEG
            # GROSS pnl straight from each persisted 'closed' event —
            # it was never fee-adjusted, so the Cumulative PnL chart and
            # the stats header (Total PnL/Avg Win/Max Drawdown/Sharpe)
            # have always reflected GROSS performance, silently
            # inconsistent with the trade table's own correctly
            # fee-adjusted NET PNL column. For 'sim' specifically, build
            # the chart/stats' own "events" from scan_all_trades_
            # detailed's ALREADY-computed per-TRADE net_pnl (entry fee
            # counted once, exit fee per leg) instead of re-deriving from
            # raw per-leg gross pnl — trades_cache is refreshed FIRST so
            # this always uses the current cycle's own fresh data, not a
            # stale value from 2s ago. 'real' mode is unaffected (no
            # per-trade fee data exists there at all — same already-
            # documented approximate-pnl gap as everywhere else in real
            # mode), still sourced from scan_all_trade_events as before.
            if trades_cache.get("source") != data_source or now_mono - trades_cache["ts"] > 2.0:
                # 2026-08-11: real mode used to always be [] here (no
                # detailed per-trade data existed yet) — now sourced from
                # scan_real_trades_detailed, the real-mode counterpart to
                # scan_all_trades_detailed (see its own docstring). Still
                # forward-only: a real trade closed before that logging
                # shipped simply won't appear.
                trades = (scan_all_trades_detailed() if data_source == "sim"
                          else scan_real_trades_detailed(snap.get("balance")))
                trades_cache = {"source": data_source, "ts": now_mono, "trades": trades}
            if data_cache["source"] != data_source or now_mono - data_cache["ts"] > 2.0:
                if data_source == "sim":
                    events = [{"ts": t["exit_ts"], "pnl": t["net_pnl"]} for t in trades_cache["trades"]]
                else:
                    events = scan_all_trade_events(data_source)
                data_cache = {"source": data_source, "ts": now_mono, "events": events,
                              "stats": compute_trade_stats(events, source=data_source,
                                                            current_balance=snap.get("balance"))}
            data_table_info = draw_data_view(db, rows, cols, data_source, data_cache["events"],
                                              data_cache["stats"], trades_cache["trades"], table_scroll, table_hscroll)
            _, _, table_scroll, table_hscroll = data_table_info
        elif gex_mode:
            # Full screen (0..rows, not 0..footer_row) — draw_gex_map/
            # draw_gex_by_strike own their entire own status/hint row at
            # the very last line, same as gex.py's own screen does, so
            # there's no separate Athena footer drawn underneath (see the
            # footer dispatch below).
            gex_asset = chart_focus if chart_focus in ASSETS else "ETH"
            gex_ui = {"live_follow": gex_live_follow[gex_asset], "view_end_idx": gex_view_end_idx[gex_asset],
                      "vert_follow": gex_vert_follow[gex_asset], "vert_center_idx": gex_vert_center_idx[gex_asset],
                      "by_strike_net": gex_by_strike_net}
            if gex_by_strike:
                draw_gex_by_strike(db, gex_asset, 0, rows, 0, cols, gex_ui)
            else:
                draw_gex_map(db, gex_asset, 0, rows, 0, cols, gex_ui)
            if mode_help_open["gex"]:
                _draw_key_menu_overlay(db, rows, cols, GEX_HELP_LINES, GEX_HELP_BOX_W, mode_help_scroll["gex"])
        elif status_mode:
            # Full screen, same convention as gex_mode above — draw_status_
            # screen draws its own hint row at the very last line, so no
            # separate Athena footer is drawn underneath (see the footer
            # dispatch below).
            status_scroll = draw_status_screen(db, 0, rows, 0, cols, status_scroll)
            if mode_help_open["status"]:
                _draw_key_menu_overlay(db, rows, cols, STATUS_HELP_LINES, STATUS_HELP_BOX_W, mode_help_scroll["status"])
        elif drift_mode:
            # Full screen, same convention as gex_mode/status_mode above —
            # draw_drift draws its own hint row at the very last line, so no
            # separate Athena footer is drawn underneath (see the footer
            # dispatch below).
            drift_asset = chart_focus if chart_focus in ASSETS else "ETH"
            drift_ui = {"live": drift_live[drift_asset], "view_date": drift_view_date[drift_asset],
                        "view_offset": drift_view_offset[drift_asset], "bar_interval": drift_bar_interval,
                        "filtered_mode": drift_filtered_mode, "net_volume_mode": drift_net_volume_mode,
                        "crosshair_idx": (drift_crosshair_idx[drift_asset] if drift_crosshair_active[drift_asset] else None)}
            drift_view_offset[drift_asset] = draw_drift(db, drift_asset, 0, rows, 0, cols, drift_ui)
            if mode_help_open["drift"]:
                _draw_key_menu_overlay(db, rows, cols, DRIFT_HELP_LINES, DRIFT_HELP_BOX_W, mode_help_scroll["drift"],
                                        close_key_hint="[H]")
        elif cvd_mode:
            # Full screen, same convention as drift_mode above — draw_cvd
            # draws its own hint row at the very last line, so no separate
            # Athena footer is drawn underneath (see the footer dispatch below).
            cvd_asset = chart_focus if chart_focus in ASSETS else "ETH"
            cvd_ui = {"live": True, "zoom_group": cvd_zoom_group, "show_btd": cvd_show_btd,
                      "color_scheme": cvd_color_scheme, "view_offset": cvd_view_offset[cvd_asset],
                      "crosshair_idx": (cvd_crosshair_idx[cvd_asset] if cvd_crosshair_active[cvd_asset] else None)}
            cvd_view_offset[cvd_asset] = draw_cvd(db, cvd_asset, 0, rows, 0, cols, cvd_ui)
            if mode_help_open["cvd"]:
                _draw_key_menu_overlay(db, rows, cols, CVD_HELP_LINES, CVD_HELP_BOX_W, mode_help_scroll["cvd"])
        elif voldrift_mode:
            # Full screen, same convention as drift_mode above — draw_voldrift
            # draws its own hint row at the very last line, so no separate
            # Athena footer is drawn underneath (see the footer dispatch below).
            voldrift_asset = chart_focus if chart_focus in ASSETS else "ETH"
            voldrift_ui = {"live": voldrift_live[voldrift_asset], "view_date": voldrift_view_date[voldrift_asset],
                           "view_offset": voldrift_view_offset[voldrift_asset], "bar_interval": voldrift_bar_interval}
            voldrift_view_offset[voldrift_asset] = draw_voldrift(db, voldrift_asset, 0, rows, 0, cols, voldrift_ui)
            if mode_help_open["voldrift"]:
                _draw_key_menu_overlay(db, rows, cols, VOLDRIFT_HELP_LINES, VOLDRIFT_HELP_BOX_W,
                                        mode_help_scroll["voldrift"], close_key_hint="[H]")
        elif macro_options_mode:
            draw_macro_options(db, rows, cols)
            if mode_help_open["macro_options"]:
                _draw_key_menu_overlay(db, rows, cols, MACRO_OPTIONS_HELP_LINES, MACRO_OPTIONS_HELP_BOX_W,
                                        mode_help_scroll["macro_options"])
        elif chain_mode:
            draw_chain(db, rows, cols, chain_simple_mode)
            if mode_help_open["chain"]:
                _draw_key_menu_overlay(db, rows, cols, CHAIN_HELP_LINES, CHAIN_HELP_BOX_W, mode_help_scroll["chain"])
        else:
            chart_top = 0 if dashboard_hidden else (DASHBOARD_H if rows - 1 > DASHBOARD_H + 10 else 0)
            if chart_top:
                draw_dashboard(db, snap, cols)
                draw_sync_status_box(db, cols)
            chart_bottom = footer_row

            both_panes = chart_bottom - chart_top > 10
            if both_panes:
                eth_inst = snap["instruments"].get("ETH") or {}
                qqq_inst = snap["instruments"].get("QQQ") or {}
                eth_bars = snap["footprint_bars"].get("ETH") or []
                qqq_bars = snap["footprint_bars"].get("QQQ") or []
                eth_live = eth_inst.get("live_price") if eth_inst.get("live_price") is not None else eth_inst.get("price")
                qqq_live = qqq_inst.get("live_price") if qqq_inst.get("live_price") is not None else qqq_inst.get("price")
                eth_live_bar = snap["live_bars"].get("ETH")
                qqq_live_bar = snap["live_bars"].get("QQQ")
                eth_1m = snap.get("ohlc_1m_bars", {}).get("ETH") or []
                qqq_1m = snap.get("ohlc_1m_bars", {}).get("QQQ") or []
                eth_1m_live = snap.get("ohlc_1m_live", {}).get("ETH")
                qqq_1m_live = snap.get("ohlc_1m_live", {}).get("QQQ")
                # VAH/VAL/POC/VWAP+SD — already computed continuously by
                # _ch_export_loop (Status engine's own background thread)
                # into CH_STATE[asset].indicator_levels; read-only snapshot
                # here rather than re-deriving Chart mode's own VP/VWAP
                # closures a second time for the OHLC panel.
                with CH_STATE["ETH"].lock:
                    eth_levels = dict(CH_STATE["ETH"].indicator_levels)
                with CH_STATE["QQQ"].lock:
                    qqq_levels = dict(CH_STATE["QQQ"].indicator_levels)
                ohlc_ui_common = dict(show_sessions=ohlc_show_sessions, line_mode=ohlc_line_mode,
                                       vp_historical=ohlc_vp_historical)
                if chart_zoom:
                    # [Z] fullscreen — whichever pane [Tab] currently has
                    # focused gets the ENTIRE chart width, same panel-
                    # drawing call as the split view just with x0=0/x1=cols
                    # instead of a half. [Tab] still works while zoomed, to
                    # flip which asset fills the screen without leaving
                    # zoom mode first.
                    zoom_asset = chart_focus
                    bars = eth_bars if zoom_asset == "ETH" else qqq_bars
                    inst = eth_inst if zoom_asset == "ETH" else qqq_inst
                    live = eth_live if zoom_asset == "ETH" else qqq_live
                    live_bar = eth_live_bar if zoom_asset == "ETH" else qqq_live_bar
                    z_1m = eth_1m if zoom_asset == "ETH" else qqq_1m
                    z_1m_live = eth_1m_live if zoom_asset == "ETH" else qqq_1m_live
                    z_levels = eth_levels if zoom_asset == "ETH" else qqq_levels
                    draw_footprint_panel(db, zoom_asset, bars, inst, chart_top, chart_bottom, 0, cols,
                                          profile_mode, build_trade_markers(zoom_asset, bars, inst, snap["trade_pairs"]),
                                          hscroll_bars=chart_scroll[zoom_asset], live_price=live, live_bar=live_bar,
                                          focused=True,
                                          market_closed=(zoom_asset == "QQQ" and snap["qqq_market_closed"]),
                                          crosshair_bar_idx=(chart_crosshair_idx[zoom_asset] if chart_crosshair_active[zoom_asset] else None),
                                          ohlc_1m_bars=z_1m, ohlc_1m_live=z_1m_live,
                                          ohlc_levels=z_levels, ohlc_targets=inst.get("targets") or [],
                                          ohlc_er=inst.get("er_bands"),
                                          ohlc_vert_offset=ohlc_vert_offset[zoom_asset],
                                          ohlc_ui=dict(ohlc_ui_common,
                                                        show_markets=(ohlc_show_markets_qqq if zoom_asset == "QQQ" else False)),
                                          ohlc_trade_events=build_trade_markers(
                                              zoom_asset, z_1m + ([z_1m_live] if z_1m_live else []),
                                              inst, snap["trade_pairs"]))
                else:
                    mid = cols // 2
                    # 2026-08-26 user request: a blank gutter between ETH's
                    # own price axis and QQQ's left edge — previously mid
                    # was both ETH's x1 AND QQQ's x0, so ETH's rightmost
                    # price-axis column sat flush against QQQ's candles
                    # with no visual separation at all.
                    pane_gap = 2
                    eth_x1 = mid - pane_gap // 2
                    qqq_x0 = mid + pane_gap // 2
                    draw_footprint_panel(db, "ETH", eth_bars, eth_inst, chart_top, chart_bottom, 0, eth_x1,
                                          profile_mode, build_trade_markers("ETH", eth_bars, eth_inst, snap["trade_pairs"]),
                                          hscroll_bars=chart_scroll["ETH"], live_price=eth_live, live_bar=eth_live_bar,
                                          focused=(chart_focus == "ETH"),
                                          crosshair_bar_idx=(chart_crosshair_idx["ETH"] if chart_crosshair_active["ETH"] else None),
                                          ohlc_1m_bars=eth_1m, ohlc_1m_live=eth_1m_live,
                                          ohlc_levels=eth_levels, ohlc_targets=eth_inst.get("targets") or [],
                                          ohlc_er=eth_inst.get("er_bands"),
                                          ohlc_vert_offset=ohlc_vert_offset["ETH"], ohlc_ui=ohlc_ui_common,
                                          ohlc_trade_events=build_trade_markers(
                                              "ETH", eth_1m + ([eth_1m_live] if eth_1m_live else []),
                                              eth_inst, snap["trade_pairs"]))
                    draw_footprint_panel(db, "QQQ", qqq_bars, qqq_inst, chart_top, chart_bottom, qqq_x0, cols,
                                          profile_mode, build_trade_markers("QQQ", qqq_bars, qqq_inst, snap["trade_pairs"]),
                                          hscroll_bars=chart_scroll["QQQ"], live_price=qqq_live, live_bar=qqq_live_bar,
                                          focused=(chart_focus == "QQQ"),
                                          market_closed=snap["qqq_market_closed"],
                                          crosshair_bar_idx=(chart_crosshair_idx["QQQ"] if chart_crosshair_active["QQQ"] else None),
                                          ohlc_1m_bars=qqq_1m, ohlc_1m_live=qqq_1m_live,
                                          ohlc_levels=qqq_levels, ohlc_targets=qqq_inst.get("targets") or [],
                                          ohlc_er=qqq_inst.get("er_bands"),
                                          ohlc_vert_offset=ohlc_vert_offset["QQQ"],
                                          ohlc_ui=dict(ohlc_ui_common, show_markets=ohlc_show_markets_qqq),
                                          ohlc_trade_events=build_trade_markers(
                                              "QQQ", qqq_1m + ([qqq_1m_live] if qqq_1m_live else []),
                                              qqq_inst, snap["trade_pairs"]))

            if mode_help_open["trading"]:
                _draw_key_menu_overlay(db, rows, cols, TRADING_HELP_LINES, TRADING_HELP_BOX_W,
                                        mode_help_scroll["trading"])

        if activity_log_open:
            draw_activity_log_popup(db, rows, cols, snap["event_log"], activity_log_scroll)

        ts = datetime.now().strftime("%H:%M:%S")
        if reset_armed:
            footer = f"{ts}   {YLW}Reset paper account — [R] again to enter a new balance, any other key to cancel{RST}"
            db.puts_ansi(footer_row, 0, footer.ljust(cols)[:cols])
        elif data_view:
            visible_rows, total, _, _ = data_table_info
            scroll_tag = ""
            if total:
                shown = min(table_scroll + 1, total)
                shown_end = min(table_scroll + visible_rows, total)
                scroll_tag = f"  [{shown}-{shown_end} of {total}, ↑/↓ scroll table, ←/→ scroll columns]"
            footer = f"{ts}   [D]ashboard   [S]witch source ({data_source}){scroll_tag}   [Q]uit"
            db.puts(footer_row, 0, footer.ljust(cols)[:cols], P_DIM)
        elif gex_mode:
            pass   # draw_gex_map/draw_gex_by_strike already drew their own
                   # full status/hint row at the screen's very last line —
                   # same as gex.py's own screen does — so there's nothing
                   # left for Athena's own generic footer to add here.
        elif status_mode:
            pass   # draw_status_screen already drew its own hint row —
                   # same reasoning as gex_mode above.
        elif drift_mode:
            pass   # draw_drift already drew its own hint row — same
                   # reasoning as gex_mode/status_mode above.
        elif cvd_mode:
            pass   # draw_cvd already drew its own hint row — same
                   # reasoning as drift_mode above.
        elif voldrift_mode:
            pass   # draw_voldrift already drew its own hint row — same
                   # reasoning as drift_mode above.
        elif macro_options_mode:
            pass   # draw_macro_options already drew its own hint row.
        elif chain_mode:
            pass   # draw_chain already drew its own hint row.
        else:
            # [Tab] hint placed right after the scroll hint it's directly
            # related to (not appended at the very end) — the footer is
            # already long enough on a modest terminal that anything tacked
            # on last just gets silently truncated by the ljust/[:cols]
            # below, which is exactly what was hiding this hint before.
            tab_hint = f" [Tab]:{chart_focus} [Z]:{'full' if chart_zoom else 'split'}" if both_panes else ""
            focus_asset = chart_focus if both_panes else "ETH"
            # Shrunk 2026-08-26 (user request — the full key list moved into
            # the new [H] help menu, see TRADING_HELP_SECTIONS) to just what's
            # genuinely glance-critical: quit, the help hint itself, per-asset
            # pause state, view mode, trading mode, live-vs-paper status
            # (safety-critical — DRY_RUN vs real money), and the one
            # emergency action ([F]latten) worth keeping one keypress away
            # from a bare footer read rather than a menu open.
            if CLIENT_MODE:
                footer = (f"{ts}  [CLIENT] {SYNC_CLIENT_STATUS[0]}  [Q]uit [H]elp [V]iew:{profile_mode}{tab_hint}"
                          + ("  [S]:dash" if dashboard_hidden else "  [S]:hide"))
            else:
                mode_hint = f" [9]:{TRADING_MODE}"
                sim_tag = ("[DRY RUN] [G]o live" if DRY_RUN else "[G]o sim")
                footer = (f"{ts}  [Q]uit [H]elp [A]:{focus_asset}:{'OFF' if not ATHENA_ENABLED[focus_asset] else 'on'}"
                          f" [V]iew:{profile_mode}{tab_hint}{mode_hint}  {sim_tag}  [F]latten"
                          + ("  [S]:dash" if dashboard_hidden else "  [S]:hide")
                          + (f"  [SRV:{len(SYNC_CLIENTS)}]" if SERVER_MODE else ""))
            db.puts(footer_row, 0, footer.ljust(cols)[:cols], P_DIM)

        db.flush(stdscr)
        stdscr.noutrefresh()
        curses.doupdate()

        key = stdscr.getch()
        if key == -1:
            continue

        # Collapse a same-direction key-repeat burst into one net scroll
        # step + one redraw — 2026-08-26 user-reported ("the menu broke
        # towards the end and then froze" scrolling the new [H] help
        # overlay): each queued repeat key otherwise got its own FULL
        # redraw (the Trading dashboard's dual-pane OHLC chart underneath
        # a help box is an expensive one — level lines, sessions overlay,
        # BTD detection, volume bars, all recomputed every frame), so a
        # fast key-repeat burst on ↑/↓ could take real, visible time to
        # drain one key at a time, reading as the UI hanging then
        # "catching up" once the user let go. Scoped to KEY_UP/KEY_DOWN
        # only (the two keys any open help menu's own scroll uses) and
        # only while some menu is actually open, so normal single-key
        # navigation elsewhere is completely unaffected.
        key_repeat_n = 1
        if key in (curses.KEY_UP, curses.KEY_DOWN) and any(mode_help_open.values()):
            stdscr.nodelay(True)
            while True:
                nxt = stdscr.getch()
                if nxt != key:
                    if nxt != -1:
                        curses.ungetch(nxt)
                    break
                key_repeat_n += 1
            stdscr.nodelay(False)
            stdscr.timeout(100)

        if reset_armed:
            reset_armed = False
            if key in (ord("r"), ord("R")):
                current = get_sim_account().balance
                new_balance = _prompt_number(stdscr, f"New paper balance (current ${current:,.2f}, Enter keeps it): $",
                                              default=current)
                db.prev = None   # dialog wrote straight to stdscr, bypassing the DoubleBuffer — force a full repaint
                _reset_sim_balance[0] = new_balance
                _reset_sim_evt.set()
            continue

        if activity_log_open:
            if key in (ord("l"), ord("L"), 27, ord("q"), ord("Q")):
                activity_log_open = False
                if key in (ord("q"), ord("Q")):
                    _quit_evt.set()
            elif key == curses.KEY_UP:
                activity_log_scroll += 1
            elif key == curses.KEY_DOWN:
                activity_log_scroll = max(0, activity_log_scroll - 1)
            elif key == curses.KEY_PPAGE:
                activity_log_scroll += 10
            elif key == curses.KEY_NPAGE:
                activity_log_scroll = max(0, activity_log_scroll - 10)
            continue

        if status_mode:
            # Scrollable full-screen text, not a chart with pan state, so
            # the key set is smaller than gex_mode's. Status is the LAST
            # stop (order: Trading -> GEX -> Net Drift -> CVD -> Volatility
            # Drift -> Chain -> Macro Options Flow -> Status -> Trading) —
            # [M] and Esc both land back on Trading here.
            if key in (ord("q"), ord("Q")):
                _quit_evt.set()
            elif key in (ord("h"), ord("H")):
                mode_help_open["status"] = not mode_help_open["status"]
                if not mode_help_open["status"]:
                    mode_help_scroll["status"] = 0
            elif key == 27 and mode_help_open["status"]:
                mode_help_open["status"] = False
                mode_help_scroll["status"] = 0
            elif key in (ord("m"), ord("M"), 27):
                status_mode = False
            elif key in (ord("k"), ord("K")):   # [K] — cycle backward: to Macro
                                                  # Options Flow (2026-08-27: Markets,
                                                  # which used to sit between them, was
                                                  # folded into a [Y] toggle on the QQQ
                                                  # OHLC pane instead of its own stop —
                                                  # see _draw_markets_panel).
                status_mode = False
                macro_options_mode = True
            elif mode_help_open["status"] and key == curses.KEY_UP:
                mode_help_scroll["status"] = max(0, mode_help_scroll["status"] - key_repeat_n)
            elif mode_help_open["status"] and key == curses.KEY_DOWN:
                mode_help_scroll["status"] = min(mode_help_scroll["status"] + key_repeat_n, _help_menu_max_scroll(len(STATUS_HELP_LINES), rows))
            elif key == curses.KEY_UP:
                status_scroll = max(0, status_scroll - 1)
            elif key == curses.KEY_DOWN:
                status_scroll += 1
            elif key == curses.KEY_PPAGE:
                status_scroll = max(0, status_scroll - 10)
            elif key == curses.KEY_NPAGE:
                status_scroll += 10
            elif key == curses.KEY_HOME:
                status_scroll = 0
            elif key == curses.KEY_END:
                status_scroll = 10 ** 9   # clamped down to the real max inside draw_status_screen
            continue

        if gex_mode:
            # Ported from gex.py's own curses_main key dispatch. One
            # deliberate adaptation: gex.py uses Esc (alongside z/Z/End)
            # to reset pan/scroll to live — Athena instead uses Esc to
            # LEAVE gex_mode, matching the same cross-mode convention
            # data_view/activity_log_open already use ([mode-key] or Esc
            # = back out). z/Z/End alone still does gex.py's own reset.
            #
            # [M] means "next mode" in the Trading -> GEX -> Net Drift ->
            # CVD -> Volatility Drift -> Chain -> Macro Options Flow ->
            # Status -> Trading cycle. Esc remains the fast "back to
            # Trading" escape hatch from any mode, unchanged.
            gex_asset = chart_focus if chart_focus in ASSETS else "ETH"
            if key in (ord("q"), ord("Q")):
                _quit_evt.set()
            elif key in (ord("h"), ord("H")):
                mode_help_open["gex"] = not mode_help_open["gex"]
                if not mode_help_open["gex"]:
                    mode_help_scroll["gex"] = 0
            elif mode_help_open["gex"] and key == curses.KEY_UP:
                mode_help_scroll["gex"] = max(0, mode_help_scroll["gex"] - key_repeat_n)
            elif mode_help_open["gex"] and key == curses.KEY_DOWN:
                mode_help_scroll["gex"] = min(mode_help_scroll["gex"] + key_repeat_n, _help_menu_max_scroll(len(GEX_HELP_LINES), rows))
            elif key == 27 and mode_help_open["gex"]:
                mode_help_open["gex"] = False
                mode_help_scroll["gex"] = 0
            elif key == 27:
                gex_mode = False
            elif key in (ord("m"), ord("M")):
                gex_mode = False
                drift_mode = True
            elif key in (ord("k"), ord("K")):   # [K] — cycle backward: GEX's own
                                                  # previous stop is Trading directly
                                                  # again (2026-08-27: Chart mode, which
                                                  # used to sit between them, was removed
                                                  # entirely — its own OHLC-panel-derived
                                                  # feed had replaced everything it did).
                gex_mode = False
            elif key in (ord("g"), ord("G")):
                gex_by_strike = not gex_by_strike
            elif key in (ord("n"), ord("N")) and gex_by_strike:
                gex_by_strike_net = not gex_by_strike_net
            elif key == 9:   # Tab — switch asset, same convention as the footprint charts
                chart_focus = "QQQ" if chart_focus == "ETH" else "ETH"
            elif key in (ord("z"), ord("Z"), curses.KEY_END):
                gex_live_follow[gex_asset] = True
                gex_vert_follow[gex_asset] = True
            elif key == curses.KEY_LEFT:
                if gex_by_strike:
                    _gex_vert_step(gex_asset, -GEX_VERT_STEP, gex_vert_follow, gex_vert_center_idx)
                else:
                    n_hist = len(GEX_HISTORY[gex_asset])
                    if gex_live_follow[gex_asset]:
                        gex_view_end_idx[gex_asset] = n_hist
                    gex_live_follow[gex_asset] = False
                    gex_view_end_idx[gex_asset] = max(1, gex_view_end_idx[gex_asset] - GEX_ARROW_STEP)
            elif key == curses.KEY_RIGHT:
                if gex_by_strike:
                    _gex_vert_step(gex_asset, GEX_VERT_STEP, gex_vert_follow, gex_vert_center_idx)
                elif not gex_live_follow[gex_asset]:
                    n_hist = len(GEX_HISTORY[gex_asset])
                    gex_view_end_idx[gex_asset] = min(n_hist, gex_view_end_idx[gex_asset] + GEX_ARROW_STEP)
                    if gex_view_end_idx[gex_asset] >= n_hist:
                        gex_live_follow[gex_asset] = True
            elif key == curses.KEY_PPAGE:
                if gex_by_strike:
                    _gex_vert_step(gex_asset, -GEX_VERT_PAGE_STEP, gex_vert_follow, gex_vert_center_idx)
                else:
                    n_hist = len(GEX_HISTORY[gex_asset])
                    if gex_live_follow[gex_asset]:
                        gex_view_end_idx[gex_asset] = n_hist
                    gex_live_follow[gex_asset] = False
                    gex_view_end_idx[gex_asset] = max(1, gex_view_end_idx[gex_asset] - GEX_PAGE_STEP)
            elif key == curses.KEY_NPAGE:
                if gex_by_strike:
                    _gex_vert_step(gex_asset, GEX_VERT_PAGE_STEP, gex_vert_follow, gex_vert_center_idx)
                elif not gex_live_follow[gex_asset]:
                    n_hist = len(GEX_HISTORY[gex_asset])
                    gex_view_end_idx[gex_asset] = min(n_hist, gex_view_end_idx[gex_asset] + GEX_PAGE_STEP)
                    if gex_view_end_idx[gex_asset] >= n_hist:
                        gex_live_follow[gex_asset] = True
            elif key == curses.KEY_UP:
                _gex_vert_step(gex_asset, GEX_VERT_STEP, gex_vert_follow, gex_vert_center_idx)
            elif key == curses.KEY_DOWN:
                _gex_vert_step(gex_asset, -GEX_VERT_STEP, gex_vert_follow, gex_vert_center_idx)
            elif key == ord("["):
                _gex_vert_step(gex_asset, GEX_VERT_PAGE_STEP, gex_vert_follow, gex_vert_center_idx)
            elif key == ord("]"):
                _gex_vert_step(gex_asset, -GEX_VERT_PAGE_STEP, gex_vert_follow, gex_vert_center_idx)
            elif key == ord("{"):
                gex_vert_follow[gex_asset] = False
                with GEX_STATE_LOCK:
                    gex_vert_center_idx[gex_asset] = max(0, len(GEX_GRID[gex_asset]) - 1)
            elif key == ord("}"):
                gex_vert_follow[gex_asset] = False
                gex_vert_center_idx[gex_asset] = 0
            continue

        if drift_mode:
            # Ported from drift.py's own curses_main key dispatch, remapped
            # per the approved plan: [M] is taken globally (next mode — same
            # as gex_mode/status_mode above; 2026-08-16: Net Drift now leads
            # to CVD instead of Volatility Drift, since CVD was inserted
            # right after it in the cycle), drift.py's own [M] (min trade $
            # threshold) moves to [T]; drift.py's [S] (switch to an
            # arbitrary symbol) is dropped entirely since Athena only ever
            # tracks ETH/QQQ — Tab switches focus between them instead,
            # matching gex_mode's own convention; drift.py's Esc (snap to
            # live) moves to [L], freeing Esc for the same cross-mode "back
            # to Trading" convention every other full-screen mode uses.
            drift_asset = chart_focus if chart_focus in ASSETS else "ETH"
            if key in (ord("q"), ord("Q")):
                _quit_evt.set()
            elif key in (ord("h"), ord("H")):
                mode_help_open["drift"] = not mode_help_open["drift"]
                if not mode_help_open["drift"]:
                    mode_help_scroll["drift"] = 0
            elif mode_help_open["drift"] and key == curses.KEY_UP:
                mode_help_scroll["drift"] = max(0, mode_help_scroll["drift"] - key_repeat_n)
            elif mode_help_open["drift"] and key == curses.KEY_DOWN:
                mode_help_scroll["drift"] = min(mode_help_scroll["drift"] + key_repeat_n, _help_menu_max_scroll(len(DRIFT_HELP_LINES), rows))
            elif key == 27 and mode_help_open["drift"]:
                mode_help_open["drift"] = False
                mode_help_scroll["drift"] = 0
            elif key == 27:
                drift_mode = False
            elif key in (ord("m"), ord("M")):
                drift_mode = False
                cvd_mode = True
            elif key in (ord("k"), ord("K")):   # [K] — cycle backward (2026-08-17 user request)
                drift_mode = False
                gex_mode = True
            elif key == 9:   # Tab — switch asset focus, same convention as gex_mode
                chart_focus = "QQQ" if chart_focus == "ETH" else "ETH"
            elif key in (ord("l"), ord("L")):   # snap back to the live edge
                drift_live[drift_asset] = True
                drift_view_date[drift_asset] = None
                drift_view_offset[drift_asset] = 0
                DRIFT_HIST_STATE.pop(drift_asset, None)
            elif key in (ord("y"), ord("Y")):   # 2026-08-26: moved off [H], now the
                                                   # full-key-menu toggle (same key
                                                   # everywhere else in the app)
                raw = _prompt_text(stdscr, [f"{drift_asset} — date to browse MM_DD_YYYY, or 'live' to return"],
                                    prompt="> ")
                db.prev = None   # dialog wrote straight to stdscr, bypassing the DoubleBuffer
                if raw is not None:
                    low = raw.strip().lower()
                    if low in ("", "live", "l"):
                        if raw.strip():   # non-empty "live"/"l" — blank Enter is a no-op cancel
                            drift_live[drift_asset] = True
                            drift_view_date[drift_asset] = None
                            drift_view_offset[drift_asset] = 0
                            DRIFT_HIST_STATE.pop(drift_asset, None)
                    else:
                        _drift_load_historical(drift_asset, raw.strip())
                        drift_view_date[drift_asset] = raw.strip()
                        drift_live[drift_asset] = False
                        drift_view_offset[drift_asset] = 0
            elif key in (ord("i"), ord("I")):
                new_interval = _prompt_number(stdscr, f"{drift_asset} poll interval in seconds, min "
                                               f"{DRIFT_MIN_INTERVAL} (current {DRIFT_INTERVAL[drift_asset]}): ",
                                               default=DRIFT_INTERVAL[drift_asset])
                db.prev = None
                DRIFT_INTERVAL[drift_asset] = max(DRIFT_MIN_INTERVAL, int(new_interval))
            elif key in (ord("b"), ord("B")):
                new_bar = _prompt_number(stdscr, f"Bar interval in seconds, min {DRIFT_MIN_BAR_INTERVAL} "
                                          f"(current {drift_bar_interval}): ", default=drift_bar_interval)
                db.prev = None
                drift_bar_interval = max(DRIFT_MIN_BAR_INTERVAL, int(new_bar))
            elif key in (ord("t"), ord("T")):
                # 2026-08-18 user request: [T] while browsing a [H]
                # historical day now re-thresholds THAT snapshot instead of
                # (invisibly) the live engine — hist_state.min_trade_usd is
                # its own separate value (seeded from the live threshold at
                # load time, see _drift_load_historical) so exploring "what
                # if" values against a past day never silently changes what
                # the live engine is actually filtering by, and vice versa.
                _drift_viewing_hist = not drift_live[drift_asset]
                _drift_hist_for_t = DRIFT_HIST_STATE.get(drift_asset) if _drift_viewing_hist else None
                if _drift_viewing_hist and _drift_hist_for_t is None:
                    _drift_viewing_hist = False   # defensive — shouldn't happen, live is the only sane fallback
                _drift_cur_min = (_drift_hist_for_t.min_trade_usd if _drift_viewing_hist
                                   else DRIFT_MIN_TRADE_USD[drift_asset])
                new_min = _prompt_number(stdscr, f"{drift_asset} min trade size in $"
                                          f"{' (historical view)' if _drift_viewing_hist else ''} "
                                          f"(current ${_drift_cur_min:,.0f}): ", default=_drift_cur_min)
                db.prev = None
                new_min = max(0.0, new_min)
                # Every trade/delta is now always captured (see
                # DRIFT_RAW_LOG_DIR_BASE's own header comment), so the
                # chart can rebuild itself from scratch at the new
                # threshold immediately, instead of only affecting
                # whatever arrives on the NEXT poll.
                if _drift_viewing_hist:
                    _drift_hist_for_t.min_trade_usd = new_min
                    with _drift_hist_for_t.lock:
                        if DRIFT_IS_CRYPTO[drift_asset]:
                            _drift_recompute_crypto_from_raw(_drift_hist_for_t, new_min)
                        else:
                            _drift_recompute_cboe_from_raw(_drift_hist_for_t, new_min)
                    console_log(f"{YLW}{drift_asset} historical view recomputed at ${new_min:,.0f} "
                                f"min trade size (via [T]){RST}")
                else:
                    DRIFT_MIN_TRADE_USD[drift_asset] = new_min
                    _drift_state_for_t = DRIFT_STATE[drift_asset]
                    with _drift_state_for_t.lock:
                        if DRIFT_IS_CRYPTO[drift_asset]:
                            _drift_recompute_crypto_from_raw(_drift_state_for_t, new_min)
                        else:
                            _drift_recompute_cboe_from_raw(_drift_state_for_t, new_min)
                    console_log(f"{YLW}{drift_asset} Net Drift recomputed at ${new_min:,.0f} "
                                f"min trade size (via [T]){RST}")
            elif key in (ord("c"), ord("C")):
                new_dz = _prompt_number(stdscr, f"{drift_asset} confidence deadzone in $ (current "
                                         f"${DRIFT_CONFIDENCE_DEADZONE[drift_asset]:,.2f}): ",
                                         default=DRIFT_CONFIDENCE_DEADZONE[drift_asset])
                db.prev = None
                DRIFT_CONFIDENCE_DEADZONE[drift_asset] = max(0.0, new_dz)
            elif key in (ord("f"), ord("F")):
                drift_filtered_mode = not drift_filtered_mode
            elif key in (ord("n"), ord("N")):
                drift_net_volume_mode = not drift_net_volume_mode
            elif key in (ord("r"), ord("R")):
                DRIFT_NEXT_POLL_TS[drift_asset] = 0.0
            elif key in (ord("x"), ord("X")):
                drift_crosshair_active[drift_asset] = not drift_crosshair_active[drift_asset]
                if drift_crosshair_active[drift_asset]:
                    # Activates at the current right edge of the view, same
                    # first-press behavior the footprint charts' own [X] has.
                    drift_crosshair_idx[drift_asset] = 0
            elif key in (curses.KEY_LEFT, curses.KEY_SLEFT, ord("["), curses.KEY_PPAGE, ord("{")):
                # 2026-08-15 user request: crosshair movement and view
                # panning are ONE function driven by the SAME key set, at
                # the SAME 1/10/50-column steps these keys have always
                # panned by ('[' is drift.py's own bracket-key alias for
                # Shift+Left's 10-column step, a fallback for terminals
                # where Shift+Arrow doesn't register as KEY_SLEFT; '{' is
                # the matching 50-column alias) — when the crosshair is
                # active these keys move IT instead of the view, auto-
                # panning at the edges via _drift_crosshair_clamp; when
                # it's off they pan the view directly, exactly as before.
                step = 50 if key in (curses.KEY_PPAGE, ord("{")) else (10 if key in (curses.KEY_SLEFT, ord("[")) else 1)
                if drift_crosshair_active[drift_asset]:
                    plot_w_est = max(1, cols - DRIFT_LEFT_W - DRIFT_RIGHT_W - 1)
                    drift_crosshair_idx[drift_asset], drift_view_offset[drift_asset] = _drift_crosshair_clamp(
                        drift_crosshair_idx[drift_asset] + step, drift_view_offset[drift_asset], plot_w_est)
                else:
                    drift_live[drift_asset] = False
                    drift_view_offset[drift_asset] += step
            elif key in (curses.KEY_RIGHT, curses.KEY_SRIGHT, ord("]"), curses.KEY_NPAGE, ord("}")):
                step = 50 if key in (curses.KEY_NPAGE, ord("}")) else (10 if key in (curses.KEY_SRIGHT, ord("]")) else 1)
                if drift_crosshair_active[drift_asset]:
                    plot_w_est = max(1, cols - DRIFT_LEFT_W - DRIFT_RIGHT_W - 1)
                    drift_crosshair_idx[drift_asset], drift_view_offset[drift_asset] = _drift_crosshair_clamp(
                        drift_crosshair_idx[drift_asset] - step, drift_view_offset[drift_asset], plot_w_est)
                else:
                    drift_view_offset[drift_asset] = max(0, drift_view_offset[drift_asset] - step)
                    if drift_view_offset[drift_asset] == 0:
                        drift_live[drift_asset] = True
            continue

        if cvd_mode:
            # Ported from cvd.py's own curses_main key dispatch, remapped to
            # Athena's own established [X]-toggle crosshair/scroll
            # convention per explicit user request (cvd.py's own
            # arrows-auto-activate-a-crosshair model isn't used here — see
            # cvd_mode's own state-declaration comment above). [G]oto,
            # [S]witch-symbol, and [P] screenshot are dropped — see this
            # mode's own header comment in the CVD section above for why.
            # cvd_view_offset lets arrows/brackets pan back through the
            # WHOLE day's own backfilled history (2026-08-17 user request —
            # previously these keys only ever moved the crosshair within
            # whatever fit on one screen, which is why panning appeared to
            # hit a wall well before session start even once the backfill
            # itself was fixed to actually reach back that far).
            cvd_asset = chart_focus if chart_focus in ASSETS else "ETH"
            cvd_state_obj = CVD_STATE[cvd_asset]
            if key in (ord("q"), ord("Q")):
                _quit_evt.set()
            elif key in (ord("h"), ord("H")):
                mode_help_open["cvd"] = not mode_help_open["cvd"]
                if not mode_help_open["cvd"]:
                    mode_help_scroll["cvd"] = 0
            elif mode_help_open["cvd"] and key == curses.KEY_UP:
                mode_help_scroll["cvd"] = max(0, mode_help_scroll["cvd"] - key_repeat_n)
            elif mode_help_open["cvd"] and key == curses.KEY_DOWN:
                mode_help_scroll["cvd"] = min(mode_help_scroll["cvd"] + key_repeat_n, _help_menu_max_scroll(len(CVD_HELP_LINES), rows))
            elif key == 27 and mode_help_open["cvd"]:
                mode_help_open["cvd"] = False
                mode_help_scroll["cvd"] = 0
            elif key == 27:
                cvd_mode = False
            elif key in (ord("m"), ord("M")):
                cvd_mode = False
                voldrift_mode = True
            elif key in (ord("k"), ord("K")):   # [K] — cycle backward (2026-08-17 user request)
                cvd_mode = False
                drift_mode = True
            elif key == 9:   # Tab — switch asset focus, same convention as drift_mode
                chart_focus = "QQQ" if chart_focus == "ETH" else "ETH"
            elif key in (curses.KEY_HOME, ord("l"), ord("L")):   # snap back to live (clears crosshair + pan)
                cvd_crosshair_active[cvd_asset] = False
                cvd_crosshair_idx[cvd_asset] = 0
                cvd_view_offset[cvd_asset] = 0
            elif key in (ord("x"), ord("X")):
                cvd_crosshair_active[cvd_asset] = not cvd_crosshair_active[cvd_asset]
                if cvd_crosshair_active[cvd_asset]:
                    cvd_crosshair_idx[cvd_asset] = 0
            elif key in (ord("z"), ord("Z")):   # rebase CVD to 0 from this point forward, same meaning as cvd.py's own
                with cvd_state_obj.lock:
                    cvd_state_obj.cvd_offset = cvd_state_obj.raw_cvd
            elif key in (ord("t"), ord("T")):
                cvd_show_btd = not cvd_show_btd
            elif key in (ord("c"), ord("C")):
                cvd_color_scheme = "blue_white" if cvd_color_scheme == "green_red" else "green_red"
            elif key in (ord("+"), ord("=")):
                cvd_zoom_group = _cvd_zoom_step(cvd_zoom_group, -1)
            elif key in (ord("-"), ord("_")):
                cvd_zoom_group = _cvd_zoom_step(cvd_zoom_group, 1)
            elif key in (ord("i"), ord("I")):
                raw = _prompt_text(stdscr, [f"{cvd_asset} — new bar interval (e.g. 1m, 3m, 500V, 100T)"], prompt="> ")
                db.prev = None   # dialog wrote straight to stdscr, bypassing the DoubleBuffer
                if raw is not None:
                    parsed = _cvd_parse_interval(raw.strip())
                    if parsed is None:
                        console_log(f"{YLW}Invalid CVD interval '{raw.strip()}' — use 1m/3m/500V/100T style{RST}")
                    else:
                        label, new_mode, new_secs, vol_th, tick_th = parsed
                        # 2026-08-17 user request: interval changes must
                        # reload from the asset's own session start (not
                        # just start empty and build forward from the
                        # switch), so the whole session's data is
                        # scrollable at the new bar spec — see
                        # _cvd_backfill_for_spec's own docstring. Runs in a
                        # background thread (REST fetch, shouldn't block
                        # the UI loop); draw_cvd shows "backfilling…" via
                        # state.buffering while it's in flight.
                        _cvd_asset_for_bf = cvd_asset
                        _cvd_session_label_for_bf = _cvd_session_label(cvd_asset)
                        threading.Thread(
                            target=lambda: console_log(
                                f"{_cvd_asset_for_bf}: CVD backfilled "
                                f"{_cvd_backfill_for_spec(_cvd_asset_for_bf, label, new_mode, new_secs, vol_th, tick_th)[0]} "
                                f"trades since {_cvd_session_label_for_bf} (bar: {label}, via [I])"
                            ),
                            daemon=True,
                        ).start()
                        cvd_crosshair_active[cvd_asset] = False
                        cvd_crosshair_idx[cvd_asset] = 0
                        cvd_view_offset[cvd_asset] = 0
                        console_log(f"{YLW}{cvd_asset} CVD interval -> {label} (via [I]) — "
                                    f"backfilling from {_cvd_session_label_for_bf}…{RST}")
            elif key in (curses.KEY_LEFT, curses.KEY_SLEFT, ord("["), curses.KEY_PPAGE, ord("{")):
                # Crosshair movement and view panning are ONE function
                # driven by the SAME key set, same merge already built for
                # drift_mode (see its own comment) — when the crosshair is
                # active these keys move IT instead, auto-panning at the
                # edges via _drift_crosshair_clamp (pure/generic, reused
                # as-is); when it's off they pan the view directly.
                step = 50 if key in (curses.KEY_PPAGE, ord("{")) else (10 if key in (curses.KEY_SLEFT, ord("[")) else 1)
                if cvd_crosshair_active[cvd_asset]:
                    plot_w_est = max(1, cols - CVD_AXIS_W)
                    cvd_crosshair_idx[cvd_asset], cvd_view_offset[cvd_asset] = _drift_crosshair_clamp(
                        cvd_crosshair_idx[cvd_asset] + step, cvd_view_offset[cvd_asset], plot_w_est)
                else:
                    cvd_view_offset[cvd_asset] += step
            elif key in (curses.KEY_RIGHT, curses.KEY_SRIGHT, ord("]"), curses.KEY_NPAGE, ord("}")):
                step = 50 if key in (curses.KEY_NPAGE, ord("}")) else (10 if key in (curses.KEY_SRIGHT, ord("]")) else 1)
                if cvd_crosshair_active[cvd_asset]:
                    plot_w_est = max(1, cols - CVD_AXIS_W)
                    cvd_crosshair_idx[cvd_asset], cvd_view_offset[cvd_asset] = _drift_crosshair_clamp(
                        cvd_crosshair_idx[cvd_asset] - step, cvd_view_offset[cvd_asset], plot_w_est)
                else:
                    cvd_view_offset[cvd_asset] = max(0, cvd_view_offset[cvd_asset] - step)
            continue

        if voldrift_mode:
            # Ported from vol-drift.py's own curses_main key dispatch, same
            # remap reasoning as drift_mode above: [M] continues the cycle
            # (Volatility Drift -> Chain — 2026-08-19: Markets/Chain's own
            # relative order reversed, Chain now comes right after
            # Volatility Drift instead of Markets); vol-drift.py's
            # [S] (switch to an arbitrary symbol) is dropped, Tab switches
            # ETH/QQQ focus instead; vol-drift.py's Esc (snap to live) moves
            # to [L], Esc here leaves the mode, matching every other
            # full-screen mode.
            voldrift_asset = chart_focus if chart_focus in ASSETS else "ETH"
            if key in (ord("q"), ord("Q")):
                _quit_evt.set()
            elif key in (ord("h"), ord("H")):
                mode_help_open["voldrift"] = not mode_help_open["voldrift"]
                if not mode_help_open["voldrift"]:
                    mode_help_scroll["voldrift"] = 0
            elif mode_help_open["voldrift"] and key == curses.KEY_UP:
                mode_help_scroll["voldrift"] = max(0, mode_help_scroll["voldrift"] - key_repeat_n)
            elif mode_help_open["voldrift"] and key == curses.KEY_DOWN:
                mode_help_scroll["voldrift"] = min(mode_help_scroll["voldrift"] + key_repeat_n, _help_menu_max_scroll(len(VOLDRIFT_HELP_LINES), rows))
            elif key == 27 and mode_help_open["voldrift"]:
                mode_help_open["voldrift"] = False
                mode_help_scroll["voldrift"] = 0
            elif key == 27:
                voldrift_mode = False
            elif key in (ord("m"), ord("M")):
                voldrift_mode = False
                chain_mode = True
                CHAIN_SYMBOL[0] = "ETH"
                CHAIN_IS_CRYPTO[0] = True
                CHAIN_DATA[0] = None
                CHAIN_ERROR[0] = ""
                chain_stop_evt[0] = threading.Event()
                chain_thread[0] = threading.Thread(target=_chain_refresh_loop,
                                                     args=(chain_stop_evt[0],), daemon=True)
                chain_thread[0].start()
            elif key in (ord("k"), ord("K")):   # [K] — cycle backward (2026-08-17 user request)
                voldrift_mode = False
                cvd_mode = True
            elif key == 9:   # Tab — switch asset focus, same convention as drift_mode
                chart_focus = "QQQ" if chart_focus == "ETH" else "ETH"
            elif key in (ord("l"), ord("L")):   # snap back to the live edge
                voldrift_live[voldrift_asset] = True
                voldrift_view_date[voldrift_asset] = None
                voldrift_view_offset[voldrift_asset] = 0
                VOLDRIFT_HIST_STATE.pop(voldrift_asset, None)
            elif key in (ord("y"), ord("Y")):   # 2026-08-26: moved off [H], now the
                                                   # full-key-menu toggle (same key
                                                   # everywhere else in the app)
                raw = _prompt_text(stdscr, [f"{voldrift_asset} — date to browse MM_DD_YYYY, or 'live' to return"],
                                    prompt="> ")
                db.prev = None   # dialog wrote straight to stdscr, bypassing the DoubleBuffer
                if raw is not None:
                    low = raw.strip().lower()
                    if low in ("", "live", "l"):
                        if raw.strip():   # non-empty "live"/"l" — blank Enter is a no-op cancel
                            voldrift_live[voldrift_asset] = True
                            voldrift_view_date[voldrift_asset] = None
                            voldrift_view_offset[voldrift_asset] = 0
                            VOLDRIFT_HIST_STATE.pop(voldrift_asset, None)
                    else:
                        _voldrift_load_historical(voldrift_asset, raw.strip())
                        voldrift_view_date[voldrift_asset] = raw.strip()
                        voldrift_live[voldrift_asset] = False
                        voldrift_view_offset[voldrift_asset] = 0
            elif key in (ord("i"), ord("I")):
                new_interval = _prompt_number(stdscr, f"{voldrift_asset} poll interval in seconds, min "
                                               f"{VOLDRIFT_MIN_INTERVAL} (current {VOLDRIFT_INTERVAL[voldrift_asset]}): ",
                                               default=VOLDRIFT_INTERVAL[voldrift_asset])
                db.prev = None
                VOLDRIFT_INTERVAL[voldrift_asset] = max(VOLDRIFT_MIN_INTERVAL, int(new_interval))
            elif key in (ord("b"), ord("B")):
                new_bar = _prompt_number(stdscr, f"Bar interval in seconds, min {VOLDRIFT_MIN_BAR_INTERVAL} "
                                          f"(current {voldrift_bar_interval}): ", default=voldrift_bar_interval)
                db.prev = None
                voldrift_bar_interval = max(VOLDRIFT_MIN_BAR_INTERVAL, int(new_bar))
            elif key in (ord("w"), ord("W")):
                new_rv = _prompt_number(stdscr, f"{voldrift_asset} realized-vol window in seconds, min "
                                         f"{VOLDRIFT_MIN_RV_WINDOW} (current {VOLDRIFT_RV_WINDOW[voldrift_asset]}): ",
                                         default=VOLDRIFT_RV_WINDOW[voldrift_asset])
                db.prev = None
                VOLDRIFT_RV_WINDOW[voldrift_asset] = max(VOLDRIFT_MIN_RV_WINDOW, int(new_rv))
            elif key in (ord("d"), ord("D")):
                new_dz = _prompt_number(stdscr, f"{voldrift_asset} divergence deadzone in percentage points, "
                                         f"min {VOLDRIFT_MIN_DIVERGENCE_DEADZONE:g} (current "
                                         f"{VOLDRIFT_DIVERGENCE_DEADZONE[voldrift_asset]:g}): ",
                                         default=VOLDRIFT_DIVERGENCE_DEADZONE[voldrift_asset])
                db.prev = None
                VOLDRIFT_DIVERGENCE_DEADZONE[voldrift_asset] = max(VOLDRIFT_MIN_DIVERGENCE_DEADZONE, new_dz)
            elif key in (ord("r"), ord("R")):
                VOLDRIFT_NEXT_POLL_TS[voldrift_asset] = 0.0
            elif key == curses.KEY_LEFT:
                voldrift_live[voldrift_asset] = False
                voldrift_view_offset[voldrift_asset] += 1
            elif key == curses.KEY_RIGHT:
                voldrift_view_offset[voldrift_asset] = max(0, voldrift_view_offset[voldrift_asset] - 1)
                if voldrift_view_offset[voldrift_asset] == 0:
                    voldrift_live[voldrift_asset] = True
            elif key in (curses.KEY_SLEFT, ord("[")):
                voldrift_live[voldrift_asset] = False
                voldrift_view_offset[voldrift_asset] += 10
            elif key in (curses.KEY_SRIGHT, ord("]")):
                voldrift_view_offset[voldrift_asset] = max(0, voldrift_view_offset[voldrift_asset] - 10)
                if voldrift_view_offset[voldrift_asset] == 0:
                    voldrift_live[voldrift_asset] = True
            elif key in (curses.KEY_PPAGE, ord("{")):
                voldrift_live[voldrift_asset] = False
                voldrift_view_offset[voldrift_asset] += 50
            elif key in (curses.KEY_NPAGE, ord("}")):
                voldrift_view_offset[voldrift_asset] = max(0, voldrift_view_offset[voldrift_asset] - 50)
                if voldrift_view_offset[voldrift_asset] == 0:
                    voldrift_live[voldrift_asset] = True
            continue

        if macro_options_mode:
            # Ported from opt_dashboard.py's own key dispatch. [M] (mute in
            # the source) collides with Athena's global "next mode" key —
            # remapped to [U], same category of remap already done for
            # drift.py's own [M] (min trade $) -> [T]. Always-on (2026-08-15
            # — per explicit user request, its data keeps refreshing in the
            # background whether or not this mode is currently displayed;
            # Esc/[M] here only change what's on screen, they no longer
            # start/stop the fetch thread). 2026-08-19: Markets/Chain's own
            # relative order reversed — [M] now continues to Markets
            # (starting its on-demand thread), [K] now goes back to Chain
            # (starting ITS on-demand thread) instead of the other way
            # around.
            if key in (ord("q"), ord("Q")):
                _quit_evt.set()
            elif key in (ord("h"), ord("H")):
                mode_help_open["macro_options"] = not mode_help_open["macro_options"]
                if not mode_help_open["macro_options"]:
                    mode_help_scroll["macro_options"] = 0
            elif mode_help_open["macro_options"] and key == curses.KEY_UP:
                mode_help_scroll["macro_options"] = max(0, mode_help_scroll["macro_options"] - key_repeat_n)
            elif mode_help_open["macro_options"] and key == curses.KEY_DOWN:
                mode_help_scroll["macro_options"] = min(mode_help_scroll["macro_options"] + key_repeat_n, _help_menu_max_scroll(len(MACRO_OPTIONS_HELP_LINES), rows))
            elif key == 27 and mode_help_open["macro_options"]:
                mode_help_open["macro_options"] = False
                mode_help_scroll["macro_options"] = 0
            elif key == 27:
                macro_options_mode = False
            elif key in (ord("m"), ord("M")):
                # 2026-08-27: [M] now goes straight to Status — Markets,
                # which used to sit between them, was folded into a [Y]
                # toggle on the QQQ OHLC pane instead of its own stop.
                macro_options_mode = False
                status_mode = True
                status_scroll = 0
            elif key in (ord("k"), ord("K")):   # [K] — cycle backward (2026-08-19: now
                                                  # goes back to Chain, not Markets)
                macro_options_mode = False
                chain_mode = True
                CHAIN_SYMBOL[0] = "ETH"
                CHAIN_IS_CRYPTO[0] = True
                CHAIN_DATA[0] = None
                CHAIN_ERROR[0] = ""
                chain_stop_evt[0] = threading.Event()
                chain_thread[0] = threading.Thread(target=_chain_refresh_loop,
                                                     args=(chain_stop_evt[0],), daemon=True)
                chain_thread[0].start()
            elif key in (ord("r"), ord("R")):
                OPTFLOW_REFRESH_EVT.set()
            elif key in (ord("u"), ord("U")):
                OPTFLOW_MUTED[0] = not OPTFLOW_MUTED[0]
            continue

        if chain_mode:
            # Ported from chain.py's own key dispatch — already single-
            # symbol/[S]-switchable, so this is the most direct port of the
            # three. Esc leaves straight to Trading (resetting CHAIN_SYMBOL
            # back to "ETH" and stopping the thread, so re-entering always
            # starts clean, matching chain.py's own launch default).
            # 2026-08-19: Markets/Chain's own relative order reversed —
            # Chain now sits between Volatility Drift and Macro Options
            # Flow (was between Macro Options Flow and Status); [M]
            # continues to Macro Options Flow (always-on, no thread start
            # needed), [K] goes back to Volatility Drift.
            if key in (ord("q"), ord("Q")):
                _quit_evt.set()
            elif key in (ord("h"), ord("H")):
                mode_help_open["chain"] = not mode_help_open["chain"]
                if not mode_help_open["chain"]:
                    mode_help_scroll["chain"] = 0
            elif mode_help_open["chain"] and key == curses.KEY_UP:
                mode_help_scroll["chain"] = max(0, mode_help_scroll["chain"] - key_repeat_n)
            elif mode_help_open["chain"] and key == curses.KEY_DOWN:
                mode_help_scroll["chain"] = min(mode_help_scroll["chain"] + key_repeat_n, _help_menu_max_scroll(len(CHAIN_HELP_LINES), rows))
            elif key == 27 and mode_help_open["chain"]:
                mode_help_open["chain"] = False
                mode_help_scroll["chain"] = 0
            elif key == 27:
                chain_mode = False
                if chain_stop_evt[0] is not None:
                    chain_stop_evt[0].set()
            elif key in (ord("m"), ord("M")):
                chain_mode = False
                if chain_stop_evt[0] is not None:
                    chain_stop_evt[0].set()
                macro_options_mode = True
            elif key in (ord("k"), ord("K")):   # [K] — cycle backward (2026-08-19: now
                                                  # goes back to Volatility Drift, not
                                                  # Macro Options Flow)
                chain_mode = False
                if chain_stop_evt[0] is not None:
                    chain_stop_evt[0].set()
                voldrift_mode = True
            elif key in (ord("r"), ord("R")):
                CHAIN_REFRESH_EVT.set()
            elif key in (ord("y"), ord("Y")):
                chain_simple_mode = not chain_simple_mode
            elif key in (ord("s"), ord("S")):
                new_symbol = _prompt_text(stdscr, ["Symbol (e.g. ETH, BTC, SPY, AAPL):"], prompt="> ")
                db.prev = None
                if new_symbol and new_symbol.strip():
                    new_symbol = new_symbol.strip().upper()
                    if new_symbol != CHAIN_SYMBOL[0]:
                        CHAIN_SYMBOL[0] = new_symbol
                        CHAIN_IS_CRYPTO[0] = new_symbol in ("ETH", "BTC")
                        with CHAIN_LOCK:
                            CHAIN_DATA[0] = None
                            CHAIN_ERROR[0] = ""
                        CHAIN_REFRESH_EVT.set()
            continue

        if data_view:
            if key in (ord("q"), ord("Q")):
                _quit_evt.set()
            elif key in (ord("d"), ord("D"), 27):   # [D] again or Esc — back to the dashboard
                data_view = False
            elif key in (ord("s"), ord("S")):
                data_source = "real" if data_source == "sim" else "sim"
                table_scroll = 0
                table_hscroll = 0
            elif key == curses.KEY_UP:
                table_scroll += 1
            elif key == curses.KEY_DOWN:
                table_scroll = max(0, table_scroll - 1)
            elif key == curses.KEY_PPAGE:
                table_scroll += 10
            elif key == curses.KEY_NPAGE:
                table_scroll = max(0, table_scroll - 10)
            elif key == curses.KEY_RIGHT:
                table_hscroll += 1   # clamped inside _draw_trades_table itself
            elif key == curses.KEY_LEFT:
                table_hscroll = max(0, table_hscroll - 1)
            continue

        if key in (ord("q"), ord("Q")):
            _quit_evt.set()
        elif CLIENT_MODE and key in CLIENT_BLOCKED_KEYS:
            # Every trading-mutating key, gated in one place rather than N
            # separate edits — see CLIENT_BLOCKED_KEYS's own module-level
            # docstring for the full list and why. reset_armed (the [R]
            # two-step confirm) needs no separate gate: it can only ever
            # become True via the [R] branch this intercepts, so it's
            # unreachable here by construction.
            console_log(f"{DIM}Not available in client mode{RST}")
        elif key in (ord("v"), ord("V")):
            _profile_mode_idx[0] = (_profile_mode_idx[0] + 1) % len(PROFILE_MODES)
        elif key in (ord("r"), ord("R")) and DRY_RUN:
            reset_armed = True
        elif key in (ord("f"), ord("F")):
            # 2026-07-28 user request: same bordered-box visual style as
            # the go-live/go-sim warning (_prompt_confirm_text), but a
            # single-keypress SCOPE PICKER instead of a type-to-confirm
            # gate — Flatten only ever touches Athena's OWN open
            # positions/orders (not account mode), so its existing
            # arm-then-confirm precedent's stakes are matched by a single
            # confirmed keypress; it just now also picks WHICH asset(s).
            scope = _prompt_flatten_scope(stdscr)
            db.prev = None   # dialog wrote straight to stdscr, bypassing the DoubleBuffer
            if scope is not None:
                _flatten_scope[0] = scope
                _flatten_all_evt.set()
        elif key in (ord("d"), ord("D")):
            data_view = True
            table_scroll = 0
            table_hscroll = 0   # always reopen scrolled to the newest trades —
                                # without this, a scroll from a PRIOR visit
                                # (e.g. to check older trades) silently stayed
                                # in effect on every later reopen, pinning the
                                # view below newly-closed trades with no
                                # visible sign why the table "stopped updating"
        elif key in (ord("l"), ord("L")):
            activity_log_open = True
            activity_log_scroll = 0
        elif key in (ord("c"), ord("C")):
            fn = take_screenshot(db)
            console_log(f"{CYN}Screenshot saved: {os.path.basename(fn)}{RST}")
            log_event("SYSTEM", "screenshot", {"file": fn})
        elif key in (ord("s"), ord("S")):   # 2026-08-26: moved off [H], now the
                                              # full-key-menu toggle (same key
                                              # everywhere else in the app)
            dashboard_hidden = not dashboard_hidden
        elif key in (ord("h"), ord("H")):
            mode_help_open["trading"] = not mode_help_open["trading"]
            if not mode_help_open["trading"]:
                mode_help_scroll["trading"] = 0
        elif mode_help_open["trading"] and key == curses.KEY_UP:
            mode_help_scroll["trading"] = max(0, mode_help_scroll["trading"] - key_repeat_n)
        elif mode_help_open["trading"] and key == curses.KEY_DOWN:
            mode_help_scroll["trading"] = min(mode_help_scroll["trading"] + key_repeat_n, _help_menu_max_scroll(len(TRADING_HELP_LINES), rows))
        elif key in (ord("n"), ord("N")):
            NO_SESSION = not NO_SESSION
            console_log(f"{YLW}Session requirement {'BYPASSED (24H mode)' if NO_SESSION else 'RE-ENABLED'} (via [N]){RST}")
            log_event("SYSTEM", "no_session_toggled", {"no_session": NO_SESSION})
        elif key in (ord("a"), ord("A")):
            # Acts on whichever pane is currently [Tab]-focused — per-asset
            # toggle (explicit user request 2026-07-24), not one shared
            # switch, so ETH and QQQ can be paused/resumed independently.
            focus_asset = chart_focus if both_panes else "ETH"
            ATHENA_ENABLED[focus_asset] = not ATHENA_ENABLED[focus_asset]
            # OFF blocks WATCHING->ARMED->confirm (no NEW entries) for THIS
            # asset only — PENDING_FILL/IN_POSITION management keeps
            # running regardless, see process_cycle's own gating, so this
            # is a genuine "stop taking new signals" pause, not "abandon
            # what's already open."
            console_log((f"{RED}{BLD}{focus_asset} PAUSED (via [A]) — no new entries; "
                          f"open positions still managed normally{RST}") if not ATHENA_ENABLED[focus_asset]
                         else f"{GRN}{BLD}{focus_asset} RESUMED (via [A]){RST}")
            log_event(focus_asset, "athena_enabled_toggled", {"enabled": ATHENA_ENABLED[focus_asset]})
        elif key == ord("0") and profile_mode != "ohlc":
            # 2026-08-27: replaces Blackjack's own [B] toggle — cycles
            # between the two SIZING_MODES (Standard/Aggressive). Guarded
            # against profile_mode=="ohlc" since [0] is already the OHLC
            # panel's own candle/line style toggle in that view (see the
            # profile_mode=="ohlc" key-dispatch block further below) —
            # same "same physical key, different meaning per context"
            # precedent [Y]/[1] etc. already establish elsewhere.
            idx = SIZING_MODES.index(SIZING_MODE)
            SIZING_MODE = SIZING_MODES[(idx + 1) % len(SIZING_MODES)]
            _save_sizing_state()
            console_log(f"{YLW}{BLD}Sizing mode: {SIZING_MODE.capitalize()}{RST} (via [0])")
            log_event("SYSTEM", "sizing_mode_changed", {"mode": SIZING_MODE})
        elif key == ord("1"):
            # 2026-08-27: replaces Blackjack's own per-asset ladder-reset
            # [1] — the drawdown de-risking ladder's 20%+ Full Stop tier
            # is account-wide (not per-asset) and deliberately does NOT
            # auto-clear, so this is now the manual "I've reviewed it,
            # resume trading" acknowledgement for THAT block instead. A
            # no-op (with its own console message) if the account isn't
            # currently blocked.
            if drawdown_gate_active():
                _clear_drawdown_block()
            else:
                console_log(f"{DIM}No active Drawdown Full Stop to clear (via [1]){RST}")
        elif key == ord("9"):
            idx = TRADING_MODES.index(TRADING_MODE)
            TRADING_MODE = TRADING_MODES[(idx + 1) % len(TRADING_MODES)]
            _save_trading_mode()
            console_log(f"{YLW}{BLD}Trading mode: {TRADING_MODE}{RST} (via [9])")
            log_event("SYSTEM", "trading_mode_changed", {"mode": TRADING_MODE})
        elif key in (ord("w"), ord("W")):
            # 2026-07-28 user request: "Allow the user to set the default SL
            # amount in points for ETH and QQQ" — acts on whichever pane is
            # [Tab]-focused, same per-asset convention [A]/[1] already use.
            # ASSETS[asset] is mutated IN PLACE rather than reassigned —
            # self.cfg = ASSETS[asset] (AthenaInstrument.__init__) is a live
            # reference, not a copy, so every existing self.cfg["sl"] read
            # site (bracket placement, position sizing, _sync_moving_tps's
            # R-distance safety guard, the dashboard's SL-distance display,
            # etc.) picks up the new value on its very next read with no
            # further plumbing needed. Does NOT retroactively change the SL
            # of an already-open position — only affects trades entered
            # AFTER this changes, same as changing PCT/RISK_DOLLARS via [P]
            # doesn't resize an already-open position either.
            w_asset = chart_focus if both_panes else "ETH"
            cur_sl = ASSETS[w_asset]["sl"]
            new_sl = _prompt_number(stdscr, f"{w_asset} SL distance in points (current {fmt_num(cur_sl)}, Enter keeps it): ",
                                     default=cur_sl)
            db.prev = None
            if new_sl is not None and new_sl > 0 and abs(new_sl - cur_sl) > 1e-9:
                console_log(f"{w_asset}: {YLW}SL distance changed {fmt_num(cur_sl)} -> {fmt_num(new_sl)} (via [W]){RST}")
                log_event(w_asset, "sl_distance_changed", {"old_sl": cur_sl, "new_sl": new_sl})
                ASSETS[w_asset]["sl"] = new_sl
        elif key in (ord("t"), ord("T")):
            # 2026-08-17 user request: "Instead of having a static imbalance
            # amount, let the user set it." — was IMBALANCE_RATIO = {"ETH":
            # 3.0, "QQQ": 5.0}, now editable per-[Tab]-focused-asset at
            # runtime, same convention [W]/[E] already use (session-only,
            # not persisted to disk). IMBALANCE_RATIO is mutated IN PLACE
            # (not reassigned) so draw_footprint_panel's own
            # IMBALANCE_RATIO.get(asset, 3.0) read picks up the new value on
            # its very next frame with no further plumbing needed.
            t_asset = chart_focus if both_panes else "ETH"
            cur_ratio = IMBALANCE_RATIO.get(t_asset, 3.0)
            new_ratio = _prompt_number(stdscr, f"{t_asset} footprint imbalance ratio (current {cur_ratio:g}x, Enter keeps it): ",
                                        default=cur_ratio)
            db.prev = None
            if new_ratio is not None and new_ratio > 0 and abs(new_ratio - cur_ratio) > 1e-9:
                console_log(f"{t_asset}: {YLW}Imbalance ratio changed {cur_ratio:g}x -> {new_ratio:g}x (via [T]){RST}")
                log_event(t_asset, "imbalance_ratio_changed", {"old_ratio": cur_ratio, "new_ratio": new_ratio})
                IMBALANCE_RATIO[t_asset] = new_ratio
        elif key in (ord("e"), ord("E")):
            # 2026-07-31 user request: "Allow the user to set the fees for
            # each asset. ETH will be in terms of % of position value
            # (default is 0.06%) and QQQ will be in terms of $ per
            # share/contract (default is $0.85)." Mirrors [W]'s exact
            # pattern (per-[Tab]-focused-asset, session-only — not
            # persisted, same as [W]/[P]) but with a different UNIT per
            # asset since the two fee models aren't just different rates:
            # ETH's prompt is in PERCENT (matching how the user described
            # it, "0.06%"), converted to/from the internal fraction
            # FEE_ETH_PCT (0.0006) on entry/display; QQQ's prompt is a
            # flat dollar amount straight onto FEE_QQQ_PER_UNIT, no
            # conversion needed.
            e_asset = chart_focus if both_panes else "ETH"
            if e_asset == "QQQ":
                cur_fee = FEE_QQQ_PER_UNIT
                new_fee = _prompt_number(stdscr, f"QQQ fee $ per share/contract (current ${cur_fee:.2f}, Enter keeps it): ",
                                          default=cur_fee)
                db.prev = None
                if new_fee is not None and new_fee >= 0 and abs(new_fee - cur_fee) > 1e-9:
                    console_log(f"QQQ: {YLW}Fee changed ${cur_fee:.2f}/unit -> ${new_fee:.2f}/unit (via [E]){RST}")
                    log_event("QQQ", "fee_changed", {"old_fee": cur_fee, "new_fee": new_fee, "unit": "per_unit"})
                    FEE_QQQ_PER_UNIT = new_fee
            else:
                cur_pct = FEE_ETH_PCT * 100
                new_pct = _prompt_number(stdscr, f"ETH fee % of position value (current {cur_pct:.4g}%, Enter keeps it): ",
                                          default=cur_pct)
                db.prev = None
                if new_pct is not None and new_pct >= 0 and abs(new_pct - cur_pct) > 1e-9:
                    console_log(f"ETH: {YLW}Fee changed {cur_pct:.4g}% -> {new_pct:.4g}% (via [E]){RST}")
                    log_event("ETH", "fee_changed", {"old_fee_pct": cur_pct, "new_fee_pct": new_pct, "unit": "pct_notional"})
                    FEE_ETH_PCT = new_pct / 100
        elif key in (ord("p"), ord("P")):
            # 2026-07-26 user request: [P] is now both the value AND the
            # $/% unit toggle in one prompt — see _prompt_risk_value's own
            # docstring. Label shows the CURRENT mode's value so the user
            # knows what a bare Enter keeps.
            cur_display = f"{PCT:g}%" if RISK_MODE == "pct" else f"${RISK_DOLLARS:,.2f}"
            new_mode, new_value = _prompt_risk_value(
                stdscr, f"Risk per trade (current {cur_display} — type e.g. 2.5%% or 50$, Enter keeps it): ",
                RISK_MODE, PCT if RISK_MODE == "pct" else RISK_DOLLARS)
            db.prev = None
            if new_mode != RISK_MODE or new_value != (PCT if RISK_MODE == "pct" else RISK_DOLLARS):
                old_display = cur_display
                new_display = f"{new_value:g}%" if new_mode == "pct" else f"${new_value:,.2f}"
                console_log(f"{YLW}Risk changed: {old_display} -> {new_display} (via [P]){RST}")
                log_event("SYSTEM", "risk_changed", {"old_mode": RISK_MODE, "old_value": cur_display,
                                                       "new_mode": new_mode, "new_value": new_display})
                RISK_MODE = new_mode
                if new_mode == "pct":
                    PCT = new_value
                else:
                    RISK_DOLLARS = new_value
        elif key in (ord("g"), ord("G")):
            # [G] toggles both directions (2026-07-25, user-reported: "I'm
            # unable to switch back to sim from live" — _go_live was
            # originally one-way-only since the user's first request only
            # ever described GOING live). _go_sim needs `snap` to warn
            # about any real position that would fall out of Athena's own
            # management the instant the switch happens.
            if DRY_RUN:
                _go_live(stdscr)
            else:
                _go_sim(stdscr, snap)
            db.prev = None   # the warning pop-up wrote straight to stdscr, bypassing
                              # the DoubleBuffer — force a full repaint next frame
        elif key == 9 and both_panes:   # Tab
            chart_focus = "QQQ" if chart_focus == "ETH" else "ETH"
        elif key in (ord("z"), ord("Z")) and both_panes:
            chart_zoom = not chart_zoom
            console_log(f"{YLW}Chart {'zoomed to ' + chart_focus if chart_zoom else 'split back to ETH/QQQ'} (via [Z]){RST}")
        elif key in (ord("m"), ord("M")):
            # 2026-08-27: [M] goes straight to GEX again — Chart mode
            # (which used to sit between Trading and GEX) was removed
            # entirely once the Trading dashboard's own OHLC panel grew
            # full feature parity with it (VP/VWAP/BTD/crosshair/trade
            # markers), leaving two independent live feeds computing "the
            # same" signals as the only reason for the mismatches users
            # kept reporting between the two.
            gex_mode = True
            console_log(f"{YLW}GEX mode — via [M]{RST}")
        elif key in (ord("k"), ord("K")):
            # [K] — cycle backward: from Trading, the "previous" stop wraps
            # to the LAST mode in the cycle (Status), symmetric with [M]
            # entering the FIRST (GEX, now that Chart is gone).
            status_mode = True
            status_scroll = 0
            console_log(f"{YLW}Status mode — via [K]{RST}")
        elif key in (ord("x"), ord("X")):
            asset = chart_focus if both_panes else "ETH"
            chart_crosshair_active[asset] = not chart_crosshair_active[asset]
            if chart_crosshair_active[asset]:
                # Activates at the current right edge of the view, same
                # first-press behavior footprint.py's own Z/X has.
                chart_crosshair_idx[asset] = chart_scroll[asset]
        elif key in (curses.KEY_LEFT, curses.KEY_SLEFT, ord("["), curses.KEY_PPAGE, ord("{")):
            # 2026-08-17 user request: the footprint chart's own scroll/
            # crosshair-move should have the same 1/10/50-bar jump lengths
            # already established for drift_mode/cvd_mode (plain arrow=1,
            # Shift+Left or '[' =10, PageUp or '{' =50) — '[\'/\'{\' are the
            # same bracket-key aliases those modes use for terminals where
            # Shift+Arrow doesn't register as KEY_SLEFT. _footprint_
            # crosshair_clamp already handles ANY overflow amount (it was
            # never limited to a single column), so no change needed there
            # — only the step size fed into it.
            step = 50 if key in (curses.KEY_PPAGE, ord("{")) else (10 if key in (curses.KEY_SLEFT, ord("[")) else 1)
            asset = chart_focus if both_panes else "ETH"
            # OHLC view scrolls through LIVE_TAPE's own 1m bars, not
            # footprint.py's 90s ones — using the footprint count here
            # (as this used to, unconditionally) silently capped OHLC
            # scrollback at whatever the 90s history happened to hold,
            # even though up to OHLC_1M_MAX_BARS of 1m history is
            # actually seeded and available (2026-08-25 user-reported:
            # "QQQ only loads back to 15:58 CT" while sitting at
            # "[SCROLLED 20b back]" — the 1m array itself had 500 bars).
            bar_count = (len(snap["ohlc_1m_bars"].get(asset) or []) if profile_mode == "ohlc"
                         else len(snap["footprint_bars"].get(asset) or []))
            if chart_crosshair_active[asset]:
                total = bar_count
                pane_cols = cols if chart_zoom else (cols // 2 if both_panes else cols)
                n_est = max(1, (pane_cols - CHART_AXIS_W) // CHART_COL_W - (1 if chart_scroll[asset] == 0 else 0))
                chart_crosshair_idx[asset], chart_scroll[asset] = _footprint_crosshair_clamp(
                    chart_crosshair_idx[asset] + step, chart_scroll[asset], total, n_est)
            else:
                max_back = max(0, bar_count - 1)
                chart_scroll[asset] = min(max_back, chart_scroll[asset] + step)
        elif key in (curses.KEY_RIGHT, curses.KEY_SRIGHT, ord("]"), curses.KEY_NPAGE, ord("}")):
            step = 50 if key in (curses.KEY_NPAGE, ord("}")) else (10 if key in (curses.KEY_SRIGHT, ord("]")) else 1)
            asset = chart_focus if both_panes else "ETH"
            if chart_crosshair_active[asset]:
                total = (len(snap["ohlc_1m_bars"].get(asset) or []) if profile_mode == "ohlc"
                         else len(snap["footprint_bars"].get(asset) or []))
                pane_cols = cols if chart_zoom else (cols // 2 if both_panes else cols)
                n_est = max(1, (pane_cols - CHART_AXIS_W) // CHART_COL_W - (1 if chart_scroll[asset] == 0 else 0))
                chart_crosshair_idx[asset], chart_scroll[asset] = _footprint_crosshair_clamp(
                    max(0, chart_crosshair_idx[asset] - step), chart_scroll[asset], total, n_est)
            else:
                chart_scroll[asset] = max(0, chart_scroll[asset] - step)
        elif key == curses.KEY_UP and profile_mode == "ohlc":
            # Vertical price-axis pan for the OHLC view — shift-the-window
            # convention, per-asset (ohlc_vert_offset). KEY_UP/KEY_DOWN are
            # otherwise unused in this dispatch (every other handler in
            # the file is gated inside a DIFFERENT mode's own block).
            asset = chart_focus if both_panes else "ETH"
            ohlc_vert_offset[asset] += 1
        elif key == curses.KEY_DOWN and profile_mode == "ohlc":
            asset = chart_focus if both_panes else "ETH"
            ohlc_vert_offset[asset] -= 1
        elif key in (ord("j"), ord("J")) and profile_mode == "ohlc":
            # Reset vertical pan only.
            asset = chart_focus if both_panes else "ETH"
            ohlc_vert_offset[asset] = 0
        elif key in (ord("o"), ord("O")) and profile_mode == "ohlc":
            ohlc_show_sessions = not ohlc_show_sessions
        elif key == ord("0") and profile_mode == "ohlc":
            ohlc_line_mode = not ohlc_line_mode
        elif key == ord("4") and profile_mode == "ohlc":
            # Toggles VAH/VAL/POC "Historical Mode" (stepped developing
            # trace) vs. "Normal Mode" (flat current-value line).
            ohlc_vp_historical = not ohlc_vp_historical
        elif key in (ord("y"), ord("Y")) and profile_mode == "ohlc":
            # 2026-08-27 — QQQ pane ONLY: swap the candle chart for the
            # Markets overview (folded in once the standalone Markets
            # mode was removed — see ohlc_show_markets_qqq's own comment).
            # No asset-focus gate needed beyond profile_mode=="ohlc" — the
            # flag itself is QQQ-only regardless of which pane is
            # currently focused/zoomed (see the ohlc_ui=dict(...,
            # show_markets=...) construction at each call site).
            ohlc_show_markets_qqq = not ohlc_show_markets_qqq
        elif key == 27 and mode_help_open["trading"]:
            mode_help_open["trading"] = False
            mode_help_scroll["trading"] = 0
        elif key in (curses.KEY_HOME, 27):   # Esc — same reset-to-live convention as footprint.py
            if both_panes:
                chart_scroll["ETH"] = chart_scroll["QQQ"] = 0
                ohlc_vert_offset["ETH"] = ohlc_vert_offset["QQQ"] = 0
            else:
                chart_scroll["ETH"] = 0
                ohlc_vert_offset["ETH"] = 0
            chart_crosshair_active["ETH"] = chart_crosshair_active["QQQ"] = False

if __name__ == "__main__":
    curses.wrapper(curses_main)